CREATE SCHEMA og_bot;

CREATE TYPE og_bot.app_role AS ENUM (
    'admin',
    'user',
    'vip',
    'og_bot',
    'dev',
    'boss'
);

CREATE FUNCTION og_bot.add_battle_reward(_user_id uuid, _earned_tenths integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  tally og_bot.battle_tallies%ROWTYPE;
  safe_reward integer := LEAST(10, GREATEST(0, COALESCE(_earned_tenths, 0)));
BEGIN
  INSERT INTO og_bot.battle_tallies(user_id, pending_tenths, rounds, total_awarded_coins, updated_at)
  VALUES (_user_id, 0, 0, 0, to_timestamp(0))
  ON CONFLICT (user_id) DO NOTHING;

  SELECT * INTO tally
  FROM og_bot.battle_tallies
  WHERE user_id = _user_id
  FOR UPDATE;

  IF tally.updated_at > now() - interval '2 seconds' THEN
    RETURN jsonb_build_object(
      'earned_tenths', 0,
      'pending_tenths', tally.pending_tenths,
      'rounds', tally.rounds,
      'rate_limited', true
    );
  END IF;

  UPDATE og_bot.battle_tallies
  SET pending_tenths = pending_tenths + safe_reward,
      rounds = rounds + 1,
      updated_at = now()
  WHERE user_id = _user_id
  RETURNING * INTO tally;

  RETURN jsonb_build_object(
    'earned_tenths', safe_reward,
    'pending_tenths', tally.pending_tenths,
    'rounds', tally.rounds,
    'rate_limited', false
  );
END;
$$;

CREATE FUNCTION og_bot.add_catchphrases(p_kind text, p_tone text, p_phrases text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE v_n int;
BEGIN
  WITH ins AS (
    INSERT INTO bot_catchphrases(kind, tone, phrase, source)
    SELECT p_kind, p_tone, left(trim(x), 160), 'generated' FROM unnest(p_phrases) x
     WHERE length(trim(x)) BETWEEN 3 AND 160
    ON CONFLICT (kind, tone, phrase) DO NOTHING RETURNING 1)
  SELECT count(*) INTO v_n FROM ins;
  RETURN v_n;
END $$;

CREATE FUNCTION og_bot.admin_delete_lexicon_phrase(p_phrase text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  IF NOT (og_bot.has_role(auth.uid(), 'admin') OR og_bot.has_role(auth.uid(), 'boss')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  DELETE FROM og_bot.og_lexicon WHERE phrase = lower(btrim(p_phrase));
  RETURN FOUND;
END $$;

CREATE FUNCTION og_bot.admin_has_vault_pass(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
  SELECT (og_bot.has_role(auth.uid(), 'boss') OR og_bot.has_role(auth.uid(), 'admin'))
    AND EXISTS (SELECT 1 FROM og_bot.vip_pass_purchases WHERE user_id = p_user);
$$;

SET default_tablespace = '';

SET default_table_access_method = heap;

CREATE TABLE og_bot.og_lexicon (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    phrase text NOT NULL,
    severity smallint DEFAULT 1 NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    notes text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT og_lexicon_severity_check CHECK (((severity >= 1) AND (severity <= 5)))
);

CREATE FUNCTION og_bot.admin_list_lexicon() RETURNS SETOF og_bot.og_lexicon
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  IF NOT (og_bot.has_role(auth.uid(), 'admin') OR og_bot.has_role(auth.uid(), 'boss')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  RETURN QUERY SELECT * FROM og_bot.og_lexicon ORDER BY severity DESC, phrase ASC;
END $$;

CREATE FUNCTION og_bot.admin_referral_audit(p_limit integer DEFAULT 100, p_search text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  q text := NULLIF(btrim(p_search), '');
  users_json jsonb;
  ledger_json jsonb;
BEGIN
  IF caller IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT og_bot.has_role(caller, 'admin') THEN RAISE EXCEPTION 'forbidden'; END IF;

  WITH base AS (
    SELECT p.id, p.email, p.display_name, p.referral_code, p.coin_balance, p.created_at,
           r.referrer_id AS bound_referrer_id,
           r.created_at  AS bound_at,
           rp.display_name AS bound_referrer_name,
           rp.email AS bound_referrer_email,
           rp.referral_code AS bound_referrer_code,
           (SELECT COUNT(*) FROM og_bot.referrals x WHERE x.referrer_id = p.id) AS invitees,
           COALESCE((SELECT SUM(t.amount) FROM og_bot.coin_transactions t
                       WHERE t.user_id = p.id AND t.type = 'referral_cashback'), 0) AS earned
      FROM og_bot.profiles p
      LEFT JOIN og_bot.referrals r ON r.referee_id = p.id
      LEFT JOIN og_bot.profiles rp ON rp.id = r.referrer_id
     WHERE q IS NULL
        OR p.email ILIKE '%'||q||'%'
        OR p.display_name ILIKE '%'||q||'%'
        OR p.referral_code ILIKE '%'||q||'%'
     ORDER BY p.created_at DESC
     LIMIT GREATEST(1, LEAST(p_limit, 500))
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(base)), '[]'::jsonb) INTO users_json FROM base;

  WITH rows AS (
    SELECT t.id, t.user_id, t.amount, t.reference, t.created_at,
           NULLIF(split_part(split_part(t.reference,'|',1),':',2),'')::uuid AS referee_id,
           COALESCE(rp.display_name, split_part(rp.email,'@',1)) AS referrer_name,
           COALESCE(pp.display_name, split_part(pp.email,'@',1)) AS referee_name
      FROM og_bot.coin_transactions t
      LEFT JOIN og_bot.profiles rp ON rp.id = t.user_id
      LEFT JOIN og_bot.profiles pp ON pp.id = NULLIF(split_part(split_part(t.reference,'|',1),':',2),'')::uuid
     WHERE t.type = 'referral_cashback'
     ORDER BY t.created_at DESC
     LIMIT 100
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(rows)), '[]'::jsonb) INTO ledger_json FROM rows;

  RETURN jsonb_build_object('users', users_json, 'ledger', ledger_json);
END;
$$;

CREATE FUNCTION og_bot.admin_referral_reconciliation(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  rows_json jsonb;
  totals jsonb;
BEGIN
  IF caller IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT (og_bot.has_role(caller, 'admin') OR og_bot.has_role(caller, 'boss')) THEN RAISE EXCEPTION 'forbidden'; END IF;

  WITH owed AS (
    SELECT * FROM og_bot.referral_owed_hundredths()
  ),
  burns AS (
    SELECT r.referrer_id, COUNT(*) AS burn_count
      FROM og_bot.coin_transactions t
      JOIN og_bot.referrals r ON r.referee_id = t.user_id
     WHERE t.amount < 0
       AND t.type IN ('generation', 'bot_token_purchase', 'sports_guide_access')
       AND t.created_at >= r.created_at
     GROUP BY r.referrer_id
  ),
  paid AS (
    SELECT user_id AS referrer_id,
           SUM(amount)::bigint AS actual_payout,
           COUNT(*) AS payout_count
      FROM og_bot.coin_transactions
     WHERE type IN ('referral_cashback', 'referral_backpay')
     GROUP BY user_id
  ),
  merged AS (
    SELECT p.id AS referrer_id,
           COALESCE(p.display_name, split_part(p.email,'@',1)) AS referrer_name,
           p.email AS referrer_email,
           p.referral_code,
           og_bot.referral_rate_pct(p.id) AS rate_pct,
           COALESCE(o.net_burned, 0)::bigint                AS total_burned,
           COALESCE(b.burn_count, 0)::bigint                AS burn_count,
           (COALESCE(o.owed_hundredths, 0) / 100)::bigint    AS expected_payout,
           COALESCE(pd.actual_payout, 0)::bigint             AS actual_payout,
           COALESCE(pd.payout_count, 0)::bigint              AS payout_count,
           COALESCE(a.pending_hundredths, 0)                 AS pending_hundredths,
           (COALESCE(pd.actual_payout, 0) - COALESCE(o.owed_hundredths, 0) / 100)::bigint AS delta
      FROM og_bot.profiles p
      LEFT JOIN owed o   ON o.referrer_id  = p.id
      LEFT JOIN burns b  ON b.referrer_id  = p.id
      LEFT JOIN paid  pd ON pd.referrer_id = p.id
      LEFT JOIN og_bot.referral_cashback_accrual a ON a.referrer_id = p.id
     WHERE COALESCE(o.net_burned,0) > 0 OR COALESCE(pd.actual_payout,0) > 0
     ORDER BY ABS(COALESCE(pd.actual_payout,0) - COALESCE(o.owed_hundredths,0) / 100) DESC,
              COALESCE(o.net_burned,0) DESC
     LIMIT GREATEST(1, LEAST(p_limit, 1000))
  )
  SELECT COALESCE(jsonb_agg(to_jsonb(merged)), '[]'::jsonb) INTO rows_json FROM merged;

  SELECT jsonb_build_object(
    'total_burned',     COALESCE(SUM((r->>'total_burned')::bigint), 0),
    'expected_payout',  COALESCE(SUM((r->>'expected_payout')::bigint), 0),
    'actual_payout',    COALESCE(SUM((r->>'actual_payout')::bigint), 0),
    'delta',            COALESCE(SUM((r->>'delta')::bigint), 0),
    'mismatches',       COALESCE(SUM(CASE WHEN (r->>'delta')::bigint <> 0 THEN 1 ELSE 0 END), 0)
  ) INTO totals
  FROM jsonb_array_elements(rows_json) r;

  RETURN jsonb_build_object('rows', rows_json, 'totals', totals);
END;
$$;

CREATE FUNCTION og_bot.admin_update_profile_label(target_user_id uuid, new_display_name text, admin_notes text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  old_name text;
  trimmed text := NULLIF(btrim(new_display_name), '');
BEGIN
  IF NOT og_bot.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF trimmed IS NULL OR length(trimmed) > 80 THEN
    RAISE EXCEPTION 'invalid_display_name';
  END IF;

  SELECT display_name INTO old_name FROM og_bot.profiles WHERE id = target_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'target_not_found';
  END IF;

  IF old_name IS NOT DISTINCT FROM trimmed THEN
    RETURN trimmed;
  END IF;

  UPDATE og_bot.profiles SET display_name = trimmed WHERE id = target_user_id;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (target_user_id, 0, 'admin_label',
            'label:' || COALESCE(old_name, '∅') || '→' || trimmed
            || COALESCE(' | ' || NULLIF(btrim(admin_notes), ''), ''));

  RETURN trimmed;
END;
$$;

CREATE FUNCTION og_bot.admin_upsert_lexicon_phrase(p_phrase text, p_severity smallint DEFAULT 1, p_enabled boolean DEFAULT true, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  clean text := lower(btrim(p_phrase));
  rid uuid;
BEGIN
  IF NOT (og_bot.has_role(auth.uid(), 'admin') OR og_bot.has_role(auth.uid(), 'boss')) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF clean IS NULL OR length(clean) < 2 OR length(clean) > 60 THEN
    RAISE EXCEPTION 'invalid_phrase';
  END IF;
  INSERT INTO og_bot.og_lexicon(phrase, severity, enabled, notes, created_by)
    VALUES (clean, COALESCE(p_severity, 1), COALESCE(p_enabled, true), NULLIF(btrim(p_notes), ''), auth.uid())
    ON CONFLICT (phrase) DO UPDATE
      SET severity = EXCLUDED.severity,
          enabled = EXCLUDED.enabled,
          notes = EXCLUDED.notes,
          updated_at = now()
    RETURNING id INTO rid;
  RETURN rid;
END $$;

CREATE FUNCTION og_bot.assign_og_vip_id(p_user uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  username text;
  candidate text;
BEGIN
  SELECT regexp_replace(display_name, '[^A-Za-z0-9]', '', 'g') INTO username
  FROM og_bot.profiles WHERE id = p_user FOR UPDATE;
  IF username IS NULL OR length(username) < 3 OR length(username) > 30 OR username !~ '[A-Za-z]' THEN
    RAISE EXCEPTION 'A valid username is required before assigning an OG VIP ID';
  END IF;
  candidate := og_bot.og_vip_id_for(username);
  UPDATE og_bot.profiles SET og_vip_id = candidate
  WHERE id = p_user AND og_vip_id IS DISTINCT FROM candidate;
  RETURN candidate;
END;
$$;

CREATE FUNCTION og_bot.audit_app_settings_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  actor uuid := auth.uid();
BEGIN
  IF actor IS NULL THEN
    RETURN NEW;
  END IF;
  IF NOT og_bot.has_role(actor, 'admin') THEN
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.value IS DISTINCT FROM OLD.value THEN
    INSERT INTO og_bot.boss_audit_log(actor_id, action, category, target_key, old_value, new_value)
      VALUES (actor, 'update', 'settings', NEW.key, OLD.value::text, NEW.value::text);
  ELSIF TG_OP = 'INSERT' THEN
    INSERT INTO og_bot.boss_audit_log(actor_id, action, category, target_key, old_value, new_value)
      VALUES (actor, 'create', 'settings', NEW.key, NULL, NEW.value::text);
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO og_bot.boss_audit_log(actor_id, action, category, target_key, old_value, new_value)
      VALUES (actor, 'delete', 'settings', OLD.key, OLD.value::text, NULL);
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION og_bot.audit_coin_deduction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  delta integer;
BEGIN
  IF NEW.coin_balance IS NULL OR OLD.coin_balance IS NULL THEN
    RETURN NEW;
  END IF;
  delta := NEW.coin_balance - OLD.coin_balance;
  IF delta < 0 THEN
    INSERT INTO og_bot.security_audit_log
      (event_type, target_user_id, actor_id, coin_delta, old_balance, new_balance, jwt_role, reason)
    VALUES
      ('coin_deduction', NEW.id, auth.uid(), delta, OLD.coin_balance, NEW.coin_balance,
       current_setting('request.jwt.claim.role', true),
       current_setting('lov.audit_reason', true));
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION og_bot.audit_song_unlock() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  IF COALESCE(NEW.unlocked, false) = true
     AND COALESCE(OLD.unlocked, false) = false THEN
    INSERT INTO og_bot.security_audit_log
      (event_type, target_user_id, actor_id, song_id, jwt_role, reason)
    VALUES
      ('song_unlocked', NEW.user_id, auth.uid(), NEW.id,
       current_setting('request.jwt.claim.role', true),
       current_setting('lov.audit_reason', true));
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION og_bot.backpay_referral_cashback(p_batch text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  o record;
  paid_coins bigint;
  pending integer;
  short_h bigint;
  coins integer;
  leftover integer;
  inserted uuid;
  leaders integer := 0;
  total integer := 0;
BEGIN
  IF p_batch IS NULL OR length(trim(p_batch)) = 0 THEN
    RAISE EXCEPTION 'batch_required';
  END IF;

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  FOR o IN SELECT * FROM og_bot.referral_owed_hundredths() WHERE owed_hundredths > 0 LOOP
    IF NOT EXISTS (SELECT 1 FROM og_bot.profiles WHERE id = o.referrer_id) THEN
      CONTINUE;
    END IF;

    INSERT INTO og_bot.referral_cashback_accrual(referrer_id) VALUES (o.referrer_id)
    ON CONFLICT (referrer_id) DO NOTHING;
    SELECT pending_hundredths INTO pending
      FROM og_bot.referral_cashback_accrual WHERE referrer_id = o.referrer_id FOR UPDATE;

    SELECT COALESCE(SUM(amount), 0) INTO paid_coins
      FROM og_bot.coin_transactions
     WHERE user_id = o.referrer_id AND type IN ('referral_cashback', 'referral_backpay');

    short_h := o.owed_hundredths - (paid_coins * 100 + pending);
    IF short_h <= 0 THEN
      CONTINUE;
    END IF;

    coins := (short_h / 100)::integer;
    leftover := pending + (short_h % 100)::integer;
    IF leftover >= 100 THEN
      coins := coins + 1;
      leftover := leftover - 100;
    END IF;

    IF coins >= 1 THEN
      INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
      VALUES (o.referrer_id, coins, 'referral_backpay', 'backpay:' || p_batch || ':' || o.referrer_id::text)
      ON CONFLICT (reference) WHERE type = 'referral_backpay' AND reference IS NOT NULL DO NOTHING
      RETURNING id INTO inserted;
      IF inserted IS NULL THEN
        CONTINUE;  -- this batch already paid this leader
      END IF;
      UPDATE og_bot.profiles SET coin_balance = coin_balance + coins WHERE id = o.referrer_id;
      INSERT INTO og_bot.user_notifications(user_id, kind, title, body, metadata)
      VALUES (
        o.referrer_id,
        'referral_backpay',
        'Referral cashback paid',
        'We recalculated your referral cashback and paid you ' || coins ||
          ' OG coin' || CASE WHEN coins = 1 THEN '' ELSE 's' END ||
          ' you were owed at ' || o.rate_pct || '%.',
        jsonb_build_object('coins', coins, 'rate_pct', o.rate_pct, 'batch', p_batch)
      );
      leaders := leaders + 1;
      total := total + coins;
    END IF;

    UPDATE og_bot.referral_cashback_accrual
       SET pending_hundredths = leftover, updated_at = now()
     WHERE referrer_id = o.referrer_id;
  END LOOP;

  RETURN jsonb_build_object('leaders_paid', leaders, 'coins_paid', total);
END;
$$;

CREATE FUNCTION og_bot.boss_burn_coins(target_user_id uuid, amount integer, boss_notes text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  new_balance integer;
BEGIN
  IF NOT (og_bot.has_role(auth.uid(), 'boss') OR og_bot.has_role(auth.uid(), 'admin')) THEN
    RAISE EXCEPTION 'Unauthorized: boss role required';
  END IF;
  IF amount IS NULL OR amount <= 0 THEN
    RAISE EXCEPTION 'amount_must_be_positive';
  END IF;

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  UPDATE og_bot.profiles
    SET coin_balance = GREATEST(0, coin_balance - amount)
    WHERE id = target_user_id
    RETURNING coin_balance INTO new_balance;

  IF new_balance IS NULL THEN
    RAISE EXCEPTION 'target_not_found';
  END IF;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (target_user_id, -amount, 'boss_burn',
            'boss_burn' || COALESCE(' | ' || NULLIF(btrim(boss_notes), ''), ''));

  RETURN new_balance;
END;
$$;

CREATE FUNCTION og_bot.boss_get_online_users(p_minutes integer DEFAULT 5) RETURNS TABLE(id uuid, display_name text, email text, last_activity_at timestamp with time zone, last_path text, last_label text, coin_balance integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
  SELECT id, display_name, email, last_activity_at, last_path, last_label, coin_balance
  FROM og_bot.profiles
  WHERE last_activity_at IS NOT NULL
    AND last_activity_at > now() - make_interval(mins => GREATEST(1, LEAST(1440, p_minutes)))
  ORDER BY last_activity_at DESC
  LIMIT 25;
$$;

CREATE FUNCTION og_bot.boss_reclaim_coins(target_user_id uuid, amount integer, boss_notes text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  target_new_balance integer;
  boss_new_balance integer;
BEGIN
  IF caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF NOT (og_bot.has_role(caller, 'boss') OR og_bot.has_role(caller, 'admin')) THEN
    RAISE EXCEPTION 'Unauthorized: boss role required';
  END IF;
  IF amount IS NULL OR amount <= 0 THEN
    RAISE EXCEPTION 'amount_must_be_positive';
  END IF;
  IF target_user_id = caller THEN
    RAISE EXCEPTION 'cannot_reclaim_from_self';
  END IF;

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  UPDATE og_bot.profiles
    SET coin_balance = coin_balance - amount
    WHERE id = target_user_id AND coin_balance >= amount
    RETURNING coin_balance INTO target_new_balance;

  IF target_new_balance IS NULL THEN
    -- distinguish between not_found vs insufficient
    IF NOT EXISTS (SELECT 1 FROM og_bot.profiles WHERE id = target_user_id) THEN
      RAISE EXCEPTION 'target_not_found';
    END IF;
    RAISE EXCEPTION 'insufficient_coins';
  END IF;

  UPDATE og_bot.profiles
    SET coin_balance = coin_balance + amount
    WHERE id = caller
    RETURNING coin_balance INTO boss_new_balance;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (target_user_id, -amount, 'boss_reclaim',
            'boss_reclaim_to:' || caller::text || COALESCE(' | ' || NULLIF(btrim(boss_notes), ''), ''));
  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (caller, amount, 'boss_reclaim_credit',
            'boss_reclaim_from:' || target_user_id::text || COALESCE(' | ' || NULLIF(btrim(boss_notes), ''), ''));

  RETURN target_new_balance;
END;
$$;

CREATE FUNCTION og_bot.cancel_song_generation(p_user uuid, p_song uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  started timestamptz;
  owner_id uuid;
  charge record;
  refund_ref text;
  new_balance integer;
BEGIN
  IF p_user IS NULL OR p_song IS NULL THEN
    RAISE EXCEPTION 'user_and_song_required';
  END IF;

  SELECT user_id INTO owner_id FROM og_bot.songs WHERE id = p_song;
  IF owner_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;
  IF owner_id <> p_user THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'forbidden');
  END IF;

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  UPDATE og_bot.songs
     SET status = 'failed',
         error_message = 'Cancelled by user',
         suno_task_id = NULL,
         failure_class = 'terminal',
         next_retry_at = NULL
   WHERE id = p_song
     AND user_id = p_user
     AND status IN ('pending', 'processing')
  RETURNING generation_started_at INTO started;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'already', true, 'refunded', 0);
  END IF;

  -- The only charge a generation run can carry is the edit fee suno-generate
  -- takes with reference 'edit:<song id>:<run start>'.
  SELECT amount, reference INTO charge
    FROM og_bot.coin_transactions
   WHERE user_id = p_user
     AND type = 'generation'
     AND amount < 0
     AND reference LIKE 'edit:' || p_song::text || ':%'
     AND (started IS NULL OR created_at >= started - interval '2 minutes')
   ORDER BY created_at DESC
   LIMIT 1;

  IF charge.reference IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'already', false, 'refunded', 0);
  END IF;

  refund_ref := 'cancel:' || charge.reference;
  IF EXISTS (
    SELECT 1 FROM og_bot.coin_transactions
     WHERE user_id = p_user AND type = 'refund' AND reference = refund_ref
  ) THEN
    RETURN jsonb_build_object('ok', true, 'already', false, 'refunded', 0);
  END IF;

  UPDATE og_bot.profiles
     SET coin_balance = coin_balance + (-charge.amount)
   WHERE id = p_user
  RETURNING coin_balance INTO new_balance;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
  VALUES (p_user, -charge.amount, 'refund', refund_ref);

  RETURN jsonb_build_object(
    'ok', true,
    'already', false,
    'refunded', -charge.amount,
    'coin_balance', new_balance
  );
END;
$$;

CREATE FUNCTION og_bot.check_generation_capacity(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  global_cap int;
  user_cap int;
  peak_cap int;
  peak_on boolean;
  global_active int;
  user_active int;
  effective_user_cap int;
BEGIN
  SELECT COALESCE((value)::int, 10) INTO global_cap FROM og_bot.app_settings WHERE key = 'max_concurrent_jobs_global';
  SELECT COALESCE((value)::int, 2) INTO user_cap FROM og_bot.app_settings WHERE key = 'max_concurrent_jobs_per_user';
  SELECT COALESCE((value)::int, 1) INTO peak_cap FROM og_bot.app_settings WHERE key = 'peak_mode_per_user';
  SELECT COALESCE((value)::boolean, false) INTO peak_on FROM og_bot.app_settings WHERE key = 'peak_mode_enabled';

  global_cap := COALESCE(global_cap, 10);
  user_cap := COALESCE(user_cap, 2);
  peak_cap := COALESCE(peak_cap, 1);
  effective_user_cap := CASE WHEN peak_on THEN peak_cap ELSE user_cap END;

  SELECT COUNT(*) INTO global_active FROM og_bot.songs
    WHERE status IN ('pending', 'processing', 'queued');
  SELECT COUNT(*) INTO user_active FROM og_bot.songs
    WHERE user_id = p_user AND status IN ('pending', 'processing', 'queued');

  IF global_active >= global_cap THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'global_capacity_full',
      'global_active', global_active, 'user_active', user_active,
      'global_cap', global_cap, 'user_cap', effective_user_cap, 'peak', peak_on);
  END IF;
  IF user_active >= effective_user_cap THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'user_capacity_full',
      'global_active', global_active, 'user_active', user_active,
      'global_cap', global_cap, 'user_cap', effective_user_cap, 'peak', peak_on);
  END IF;

  RETURN jsonb_build_object('ok', true,
    'global_active', global_active, 'user_active', user_active,
    'global_cap', global_cap, 'user_cap', effective_user_cap, 'peak', peak_on);
END;
$$;

CREATE FUNCTION og_bot.claim_daily_drop() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  uid uuid := auth.uid();
  today date := (now() AT TIME ZONE 'utc')::date;
  reward integer;
  new_balance integer;
  inserted_id uuid;
BEGIN
  IF uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  reward := 1 + floor(random() * 3)::int; -- 1..3 coins

  INSERT INTO og_bot.daily_drops(user_id, drop_date, coins)
  VALUES (uid, today, reward)
  ON CONFLICT (user_id, drop_date) DO NOTHING
  RETURNING id INTO inserted_id;

  IF inserted_id IS NULL THEN
    SELECT coin_balance INTO new_balance FROM og_bot.profiles WHERE id = uid;
    RETURN jsonb_build_object(
      'claimed', false,
      'coins', 0,
      'balance', COALESCE(new_balance, 0),
      'next_claim_at', ((today + 1)::timestamp AT TIME ZONE 'utc')
    );
  END IF;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
  VALUES (uid, reward, 'daily_drop', 'daily_drop:' || uid::text || ':' || today::text);

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  UPDATE og_bot.profiles
  SET coin_balance = COALESCE(coin_balance, 0) + reward
  WHERE id = uid
  RETURNING coin_balance INTO new_balance;

  IF new_balance IS NULL THEN
    RAISE EXCEPTION 'profile_not_found';
  END IF;

  RETURN jsonb_build_object(
    'claimed', true,
    'coins', reward,
    'balance', new_balance,
    'next_claim_at', ((today + 1)::timestamp AT TIME ZONE 'utc')
  );
END;
$$;

CREATE TABLE og_bot.songs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    prompt text NOT NULL,
    style text,
    lyrics text,
    title text,
    status text DEFAULT 'pending'::text NOT NULL,
    suno_task_id text,
    suno_clip_id text,
    audio_path text,
    cover_url text,
    duration_seconds numeric,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    completed_at timestamp with time zone,
    unlocked boolean DEFAULT false NOT NULL,
    portal_id uuid,
    sample_path text,
    is_variation boolean DEFAULT false NOT NULL,
    revealed boolean DEFAULT true NOT NULL,
    generation_started_at timestamp with time zone,
    stream_audio_url text,
    lyrics_progress smallint,
    lyrics_stage text,
    lyrics_started_at timestamp with time zone,
    extra_context text,
    lyric_video_preview_path text,
    lyric_video_full_path text,
    lyric_video_status text DEFAULT 'idle'::text NOT NULL,
    lyric_video_unlocked boolean DEFAULT false NOT NULL,
    lyric_video_rendered_at timestamp with time zone,
    lyric_video_error text,
    lyric_video_progress integer DEFAULT 0 NOT NULL,
    lyric_video_stage text,
    vocals_only boolean DEFAULT false NOT NULL,
    beat_path text,
    target_duration_sec integer,
    drive_audio_id text,
    drive_audio_link text,
    drive_lyrics_id text,
    drive_lyrics_link text,
    drive_archived_at timestamp with time zone,
    is_public boolean DEFAULT false NOT NULL,
    foul_mouth boolean DEFAULT false NOT NULL,
    foul_intensity smallint DEFAULT 0 NOT NULL,
    retry_count integer DEFAULT 0 NOT NULL,
    next_retry_at timestamp with time zone,
    last_auto_retry_at timestamp with time zone,
    failure_class text,
    retry_payload jsonb,
    unlocked_at timestamp with time zone,
    is_nasheed boolean DEFAULT false NOT NULL,
    stem_task_id text,
    stem_source_clip_id text,
    orchestration jsonb,
    orchestration_due_at timestamp with time zone,
    orchestration_attempts integer DEFAULT 0 NOT NULL,
    CONSTRAINT songs_failure_class_valid CHECK (((failure_class IS NULL) OR (failure_class = ANY (ARRAY['recoverable_cdn'::text, 'retryable'::text, 'terminal'::text])))),
    CONSTRAINT songs_foul_intensity_check CHECK (((foul_intensity >= 0) AND (foul_intensity <= 3))),
    CONSTRAINT songs_retry_count_nonnegative CHECK ((retry_count >= 0))
);

ALTER TABLE ONLY og_bot.songs REPLICA IDENTITY FULL;

CREATE FUNCTION og_bot.claim_due_orchestrations(p_limit integer DEFAULT 2) RETURNS SETOF og_bot.songs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  IF current_setting('request.jwt.claim.role', true) <> 'service_role' THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;
  RETURN QUERY
  WITH due AS (
    SELECT s.id FROM og_bot.songs s
    WHERE s.orchestration IS NOT NULL
      AND s.status = 'draft'
      AND s.orchestration_due_at <= now()
      AND s.orchestration_attempts < 3
      AND s.created_at > now() - interval '6 hours'
    ORDER BY s.orchestration_due_at
    FOR UPDATE SKIP LOCKED
    LIMIT greatest(1, least(coalesce(p_limit, 2), 3))
  )
  UPDATE og_bot.songs s
  SET orchestration_attempts = s.orchestration_attempts + 1,
      orchestration_due_at = now() + interval '10 minutes'
  FROM due WHERE s.id = due.id
  RETURNING s.*;
END;
$$;

CREATE FUNCTION og_bot.claim_due_song_retries(p_limit integer DEFAULT 3) RETURNS SETOF og_bot.songs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  IF current_setting('request.jwt.claim.role', true) <> 'service_role' THEN
    RAISE EXCEPTION 'Forbidden';
  END IF;

  RETURN QUERY
  WITH due AS (
    SELECT s.id
    FROM og_bot.songs s
    WHERE s.next_retry_at <= now()
      AND s.retry_count < 5
      AND coalesce(s.failure_class, 'retryable') <> 'terminal'
      AND s.status IN ('failed', 'processing')
    ORDER BY s.next_retry_at, s.created_at
    FOR UPDATE SKIP LOCKED
    LIMIT greatest(1, least(coalesce(p_limit, 3), 3))
  )
  UPDATE og_bot.songs s
  SET status = 'pending',
      retry_count = s.retry_count + 1,
      last_auto_retry_at = now(),
      next_retry_at = NULL,
      error_message = NULL
  FROM due
  WHERE s.id = due.id
  RETURNING s.*;
END;
$$;

CREATE FUNCTION og_bot.claim_guest_battle(_user_id uuid, _guest_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $_$
DECLARE
  moved integer := 0;
  earned integer := 0;
BEGIN
  IF _user_id IS NULL OR _guest_id IS NULL OR _guest_id !~ '^[A-Za-z0-9-]{16,64}$' THEN
    RAISE EXCEPTION 'user_and_guest_required';
  END IF;

  WITH m AS (
    UPDATE og_bot.community_messages
       SET user_id = _user_id
     WHERE guest_id = _guest_id
       AND user_id IS NULL
       AND role = 'user'
    RETURNING COALESCE(score_tenths, 0) AS s
  )
  SELECT COUNT(*)::integer, COALESCE(SUM(s), 0)::integer INTO moved, earned FROM m;

  -- Preserve scored winnings; scoring already applies the daily reward limit.
  earned := LEAST(GREATEST(earned, 0), 50);
  IF moved = 0 OR earned = 0 THEN
    RETURN jsonb_build_object('claimed', moved, 'credited_tenths', 0);
  END IF;

  INSERT INTO og_bot.guest_battle_claims (user_id, guest_id, credited_tenths)
  VALUES (_user_id, _guest_id, earned)
  ON CONFLICT DO NOTHING;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('claimed', moved, 'credited_tenths', 0);
  END IF;

  INSERT INTO og_bot.battle_tallies (user_id, pending_tenths, rounds, total_awarded_coins, updated_at)
  VALUES (_user_id, 0, 0, 0, to_timestamp(0))
  ON CONFLICT (user_id) DO NOTHING;

  UPDATE og_bot.battle_tallies
     SET pending_tenths = pending_tenths + earned,
         rounds = rounds + moved
   WHERE user_id = _user_id;

  RETURN jsonb_build_object('claimed', moved, 'credited_tenths', earned);
END;
$_$;

CREATE FUNCTION og_bot.claim_presence_alert(p_user uuid, p_kind text, p_cooldown_minutes integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE n int;
BEGIN
  INSERT INTO og_bot.boss_presence_alerts(user_id, kind, last_sent_at)
  VALUES (p_user, p_kind, now())
  ON CONFLICT (user_id, kind) DO UPDATE SET last_sent_at = now()
  WHERE boss_presence_alerts.last_sent_at < now() - make_interval(mins => p_cooldown_minutes);
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n > 0;
END $$;

CREATE FUNCTION og_bot.claim_referral(p_referrer uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  caller_created timestamptz;
BEGIN
  IF caller IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_referrer IS NULL OR p_referrer = caller THEN RETURN false; END IF;

  -- Caller must be a real profile and < 24h old
  SELECT created_at INTO caller_created FROM og_bot.profiles WHERE id = caller;
  IF caller_created IS NULL THEN RETURN false; END IF;
  IF caller_created < now() - interval '24 hours' THEN RETURN false; END IF;

  -- Referrer must exist
  IF NOT EXISTS (SELECT 1 FROM og_bot.profiles WHERE id = p_referrer) THEN
    RETURN false;
  END IF;

  INSERT INTO og_bot.referrals(referee_id, referrer_id)
    VALUES (caller, p_referrer)
    ON CONFLICT (referee_id) DO NOTHING;

  RETURN FOUND;
END;
$$;

CREATE FUNCTION og_bot.claim_referrer_permanent(p_referrer uuid, p_acknowledged boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  existing uuid;
BEGIN
  IF caller IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_acknowledged IS NOT TRUE THEN RAISE EXCEPTION 'acknowledgement_required'; END IF;
  IF p_referrer IS NULL OR p_referrer = caller THEN RAISE EXCEPTION 'invalid_referrer'; END IF;

  SELECT referrer_id INTO existing FROM og_bot.referrals WHERE referee_id = caller;
  IF existing IS NOT NULL THEN
    RAISE EXCEPTION 'already_has_referrer';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM og_bot.profiles WHERE id = p_referrer) THEN
    RAISE EXCEPTION 'referrer_not_found';
  END IF;

  INSERT INTO og_bot.referrals(referee_id, referrer_id)
    VALUES (caller, p_referrer);

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (caller, 0, 'referral_bind', 'permanent_bind_to:' || p_referrer::text);

  RETURN jsonb_build_object('ok', true, 'referrer_id', p_referrer);
END;
$$;

CREATE FUNCTION og_bot.clawback_stripe_purchase(_user_id uuid, _purchase_reference text, _refund_id text, _mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  coins integer;
  bal integer;
  clawback_ref text := 'stripe:clawback:' || _purchase_reference;
BEGIN
  IF _user_id IS NULL OR _purchase_reference IS NULL OR length(trim(_purchase_reference)) = 0 THEN
    RAISE EXCEPTION 'user_and_reference_required';
  END IF;
  IF _mode NOT IN ('webhook', 'instant') THEN
    RAISE EXCEPTION 'invalid_mode';
  END IF;

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  -- Serialise every clawback for this user so the checks below are race-free.
  SELECT coin_balance INTO bal FROM og_bot.profiles WHERE id = _user_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile_not_found';
  END IF;

  SELECT amount INTO coins
    FROM og_bot.coin_transactions
   WHERE reference = _purchase_reference AND type = 'stripe_purchase'
   LIMIT 1;
  IF COALESCE(coins, 0) <= 0 THEN
    RETURN jsonb_build_object('clawed_back', false, 'reason', 'no_purchase', 'balance', bal);
  END IF;

  -- Already reversed by either path (or by a legacy per-refund webhook row).
  IF EXISTS (
    SELECT 1 FROM og_bot.coin_transactions
     WHERE user_id = _user_id
       AND (
         (type = 'stripe_refund' AND reference = clawback_ref)
         OR (type = 'refund' AND reference = _purchase_reference)
         OR (_refund_id IS NOT NULL AND type = 'stripe_refund' AND reference = 'stripe:refund:' || _refund_id)
       )
  ) THEN
    RETURN jsonb_build_object('clawed_back', false, 'reason', 'already_applied', 'balance', bal);
  END IF;

  IF _mode = 'instant' AND COALESCE(bal, 0) < coins THEN
    RETURN jsonb_build_object('clawed_back', false, 'reason', 'coins_spent', 'balance', bal);
  END IF;

  UPDATE og_bot.profiles
     SET coin_balance = coin_balance - coins
   WHERE id = _user_id
  RETURNING coin_balance INTO bal;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
  VALUES (
    _user_id,
    -coins,
    CASE WHEN _mode = 'instant' THEN 'refund' ELSE 'stripe_refund' END,
    CASE WHEN _mode = 'instant' THEN _purchase_reference ELSE clawback_ref END
  );

  RETURN jsonb_build_object('clawed_back', true, 'coins', coins, 'balance', bal);
END;
$$;

CREATE FUNCTION og_bot.consume_chat_image_edit(p_user uuid, p_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE v_last timestamptz; v_bal integer;
BEGIN
  INSERT INTO chat_image_allowance(user_id) VALUES (p_user) ON CONFLICT DO NOTHING;
  SELECT last_free_at INTO v_last FROM chat_image_allowance WHERE user_id = p_user FOR UPDATE;
  IF v_last IS NULL OR v_last <= now() - interval '4 hours' THEN
    UPDATE chat_image_allowance SET last_free_at = now(), updated_at = now() WHERE user_id = p_user;
    RETURN jsonb_build_object('free', true, 'cost', 0, 'prev_free_at', v_last);
  END IF;
  v_bal := og_bot.deduct_coins(p_user, 1, p_reference);
  RETURN jsonb_build_object('free', false, 'cost', 1, 'balance', v_bal,
    'next_free_at', v_last + interval '4 hours');
END $$;

CREATE FUNCTION og_bot.create_og_bot_invite(p_claim_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_token_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_notes text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  new_code text;
BEGIN
  IF NOT og_bot.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  new_code := og_bot.gen_og_bot_invite_code();

  INSERT INTO og_bot.og_bot_token_invites(code, created_by, claim_expires_at, token_expires_at, notes)
    VALUES (new_code, auth.uid(), p_claim_expires_at, p_token_expires_at, NULLIF(btrim(p_notes), ''));

  RETURN new_code;
END;
$$;

CREATE FUNCTION og_bot.credit_coin_transaction(_user_id uuid, _amount integer, _type text, _reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  inserted_tx_id uuid;
  new_balance integer;
BEGIN
  IF _user_id IS NULL THEN
    RAISE EXCEPTION 'user_id_required';
  END IF;

  IF _amount <= 0 THEN
    RAISE EXCEPTION 'amount_must_be_positive';
  END IF;

  IF _type IS NULL OR length(trim(_type)) = 0 THEN
    RAISE EXCEPTION 'type_required';
  END IF;

  IF _reference IS NULL OR length(trim(_reference)) = 0 THEN
    RAISE EXCEPTION 'reference_required';
  END IF;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
  VALUES (_user_id, _amount, _type, _reference)
  ON CONFLICT (reference) WHERE type = 'stripe_purchase' AND reference IS NOT NULL DO NOTHING
  RETURNING id INTO inserted_tx_id;

  IF inserted_tx_id IS NULL THEN
    SELECT coin_balance INTO new_balance
    FROM og_bot.profiles
    WHERE id = _user_id;

    RETURN jsonb_build_object(
      'credited', false,
      'balance', COALESCE(new_balance, 0)
    );
  END IF;

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  UPDATE og_bot.profiles
  SET coin_balance = COALESCE(coin_balance, 0) + _amount
  WHERE id = _user_id
  RETURNING coin_balance INTO new_balance;

  IF new_balance IS NULL THEN
    DELETE FROM og_bot.coin_transactions WHERE id = inserted_tx_id;
    RAISE EXCEPTION 'profile_not_found';
  END IF;

  RETURN jsonb_build_object(
    'credited', true,
    'balance', new_balance
  );
END;
$$;

CREATE FUNCTION og_bot.credit_payment_referral(_referee_id uuid, _reward_coins integer, _payment_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  referrer_id_value uuid;
  inserted_tx_id uuid;
  new_balance integer;
  reward_reference text;
BEGIN
  IF _referee_id IS NULL THEN
    RAISE EXCEPTION 'referee_id_required';
  END IF;
  IF _reward_coins <= 0 THEN
    RAISE EXCEPTION 'reward_must_be_positive';
  END IF;
  IF _payment_reference IS NULL OR length(trim(_payment_reference)) = 0 THEN
    RAISE EXCEPTION 'payment_reference_required';
  END IF;

  SELECT referrer_id INTO referrer_id_value
  FROM og_bot.referrals
  WHERE referee_id = _referee_id;

  IF referrer_id_value IS NULL THEN
    RETURN jsonb_build_object('credited', false, 'reason', 'no_referrer');
  END IF;

  reward_reference := 'payment:referee:' || _referee_id::text || '|ref:' || trim(_payment_reference);

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
  VALUES (referrer_id_value, _reward_coins, 'referral_payment', reward_reference)
  ON CONFLICT (reference) WHERE type = 'referral_payment' AND reference IS NOT NULL DO NOTHING
  RETURNING id INTO inserted_tx_id;

  IF inserted_tx_id IS NULL THEN
    SELECT coin_balance INTO new_balance FROM og_bot.profiles WHERE id = referrer_id_value;
    RETURN jsonb_build_object(
      'credited', false,
      'reason', 'already_credited',
      'referrer_id', referrer_id_value,
      'balance', COALESCE(new_balance, 0)
    );
  END IF;

  UPDATE og_bot.profiles
  SET coin_balance = COALESCE(coin_balance, 0) + _reward_coins
  WHERE id = referrer_id_value
  RETURNING coin_balance INTO new_balance;

  IF new_balance IS NULL THEN
    DELETE FROM og_bot.coin_transactions WHERE id = inserted_tx_id;
    RAISE EXCEPTION 'referrer_profile_not_found';
  END IF;

  RETURN jsonb_build_object(
    'credited', true,
    'referrer_id', referrer_id_value,
    'reward_coins', _reward_coins,
    'balance', new_balance
  );
END;
$$;

CREATE FUNCTION og_bot.daily_coin_floor() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  affected integer := 0;
BEGIN
  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  WITH old AS (
    SELECT id, coin_balance FROM og_bot.profiles
     WHERE coin_balance >= 0 AND coin_balance < 10
       FOR UPDATE
  ),
  bumped AS (
    UPDATE og_bot.profiles p
       SET coin_balance = 10
      FROM old
     WHERE p.id = old.id
       AND p.coin_balance >= 0
       AND p.coin_balance < 10
    RETURNING p.id, old.coin_balance AS prev
  ),
  logged AS (
    INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    SELECT id, 10 - prev, 'daily_floor', 'daily_floor:from_' || prev::text || '_to_10'
      FROM bumped
    RETURNING 1
  )
  SELECT count(*) INTO affected FROM logged;

  RETURN affected;
END;
$$;

CREATE FUNCTION og_bot.deduct_coins(p_user uuid, p_amount integer, p_reference text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $_$
DECLARE
  new_balance integer; existing_count integer;
BEGIN
  IF auth.uid() IS NOT NULL AND auth.uid() <> p_user THEN RAISE EXCEPTION 'forbidden_self_only'; END IF;
  IF p_amount <= 0 THEN RAISE EXCEPTION 'amount_must_be_positive'; END IF;
  PERFORM set_config('request.jwt.claim.role', 'service_role', true);
  IF p_reference IS NOT NULL AND p_reference ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    PERFORM 1 FROM og_bot.profiles WHERE id = p_user FOR UPDATE;
    SELECT COUNT(*) INTO existing_count FROM og_bot.coin_transactions
      WHERE user_id = p_user AND reference = p_reference AND type = 'generation';
    IF existing_count > 0 THEN
      SELECT coin_balance INTO new_balance FROM og_bot.profiles WHERE id = p_user;
      RETURN new_balance;
    END IF;
  END IF;
  UPDATE og_bot.profiles SET coin_balance = coin_balance - p_amount
    WHERE id = p_user AND coin_balance >= p_amount RETURNING coin_balance INTO new_balance;
  IF new_balance IS NULL THEN RAISE EXCEPTION 'insufficient_coins'; END IF;
  BEGIN
    INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
      VALUES (p_user, -p_amount, 'generation', p_reference);
  EXCEPTION WHEN unique_violation THEN
    UPDATE og_bot.profiles SET coin_balance = coin_balance + p_amount WHERE id = p_user
      RETURNING coin_balance INTO new_balance;
    RETURN new_balance;
  END;
  -- A cashback problem must never block the member's own spend.
  BEGIN
    PERFORM og_bot.pay_referral_cashback(p_user, p_amount, p_reference);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'referral cashback failed for % (%): %', p_user, p_reference, SQLERRM;
  END;
  RETURN new_balance;
END;
$_$;

CREATE FUNCTION og_bot.dev_override_balance(target_user_id uuid, new_balance integer, dev_notes text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  old_balance integer;
  delta integer;
BEGIN
  IF NOT (og_bot.has_role(auth.uid(), 'dev') OR og_bot.has_role(auth.uid(), 'admin')) THEN
    RAISE EXCEPTION 'Unauthorized: dev role required';
  END IF;
  IF new_balance IS NULL OR new_balance < 0 THEN
    RAISE EXCEPTION 'balance_out_of_range';
  END IF;

  SELECT coin_balance INTO old_balance FROM og_bot.profiles WHERE id = target_user_id;
  IF old_balance IS NULL THEN
    RAISE EXCEPTION 'target_not_found';
  END IF;

  delta := new_balance - old_balance;

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);
  UPDATE og_bot.profiles SET coin_balance = new_balance WHERE id = target_user_id;

  IF delta <> 0 THEN
    INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
      VALUES (target_user_id, delta, 'dev_override',
              'dev_override' || COALESCE(' | ' || NULLIF(btrim(dev_notes), ''), ''));
  END IF;

  RETURN new_balance;
END;
$$;

CREATE FUNCTION og_bot.dev_send_og_message_as_bot(target_user_id uuid, message_content text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  trimmed text := NULLIF(btrim(message_content), '');
  new_id uuid;
BEGIN
  IF caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF NOT (og_bot.has_role(caller, 'dev'::og_bot.app_role)
       OR og_bot.has_role(caller, 'admin'::og_bot.app_role)) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF trimmed IS NULL OR length(trimmed) > 4000 THEN
    RAISE EXCEPTION 'invalid_content';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM og_bot.profiles WHERE id = target_user_id) THEN
    RAISE EXCEPTION 'target_not_found';
  END IF;

  INSERT INTO og_bot.og_messages(user_id, role, content)
    VALUES (target_user_id, 'assistant', trimmed)
    RETURNING id INTO new_id;

  RETURN new_id;
END;
$$;

CREATE FUNCTION og_bot.ensure_member() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE u auth.users%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN RETURN false; END IF;
  IF EXISTS (SELECT 1 FROM og_bot.profiles WHERE id = auth.uid()) THEN RETURN true; END IF;
  SELECT * INTO u FROM auth.users WHERE id = auth.uid();
  IF NOT FOUND THEN RETURN false; END IF;
  INSERT INTO og_bot.profiles (id, email, display_name, coin_balance)
  VALUES (u.id, u.email, COALESCE(u.raw_user_meta_data->>'display_name', split_part(u.email, '@', 1)), 0)
  ON CONFLICT (id) DO NOTHING;
  RETURN true;
END;
$$;

