    LANGUAGE sql
    SET search_path TO 'og_bot'
    AS $$
  SELECT 'ogi_' || replace(gen_random_uuid()::text, '-', '')
                || replace(gen_random_uuid()::text, '-', '');
$$;

CREATE FUNCTION og_bot.gen_og_bot_token() RETURNS text
    LANGUAGE sql
    SET search_path TO 'og_bot'
    AS $$
  SELECT 'ogb_' || replace(gen_random_uuid()::text, '-', '')
                || replace(gen_random_uuid()::text, '-', '');
$$;

CREATE FUNCTION og_bot.gen_og_referral_code() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  alphabet text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  code text;
  attempts int := 0;
BEGIN
  LOOP
    code := 'OG-';
    FOR i IN 1..6 LOOP
      code := code || substr(alphabet, 1 + floor(random() * length(alphabet))::int, 1);
    END LOOP;
    IF NOT EXISTS (SELECT 1 FROM og_bot.profiles WHERE referral_code = code) THEN
      RETURN code;
    END IF;
    attempts := attempts + 1;
    IF attempts > 20 THEN
      RETURN 'OG-' || substr(replace(gen_random_uuid()::text,'-',''),1,8);
    END IF;
  END LOOP;
END $$;

CREATE FUNCTION og_bot.get_my_referrer() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  ref RECORD;
BEGIN
  IF caller IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT r.referrer_id,
         r.created_at AS bound_at,
         COALESCE(p.display_name, split_part(p.email,'@',1), 'Unknown') AS name,
         p.referral_code AS code
    INTO ref
    FROM og_bot.referrals r
    LEFT JOIN og_bot.profiles p ON p.id = r.referrer_id
    WHERE r.referee_id = caller;
  IF ref.referrer_id IS NULL THEN
    RETURN jsonb_build_object('has_referrer', false);
  END IF;
  RETURN jsonb_build_object(
    'has_referrer', true,
    'referrer_id', ref.referrer_id,
    'referrer_name', ref.name,
    'referrer_code', ref.code,
    'bound_at', ref.bound_at
  );
END $$;

CREATE FUNCTION og_bot.get_referral_summary() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  total_refs integer;
  total_earned integer;
  recent jsonb;
BEGIN
  IF caller IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT COUNT(*) INTO total_refs FROM og_bot.referrals WHERE referrer_id = caller;
  SELECT COALESCE(SUM(amount), 0) INTO total_earned
    FROM og_bot.coin_transactions
    WHERE user_id = caller
      AND type IN ('referral_cashback', 'referral_payment', 'referral_payment_reversal', 'referral_backpay');

  WITH rows AS (
    SELECT t.id, t.amount, t.type, t.reference, t.created_at,
           substring(t.reference FROM 'referee:([0-9a-fA-F-]{36})')::uuid AS referee_id
    FROM og_bot.coin_transactions t
    WHERE t.user_id = caller
      AND t.type IN ('referral_cashback', 'referral_payment', 'referral_payment_reversal', 'referral_backpay')
      AND NOT (t.type = 'referral_payment_reversal' AND t.amount = 0)
    ORDER BY t.created_at DESC
    LIMIT 20
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', r.id,
    'amount', r.amount,
    'type', r.type,
    'reference', r.reference,
    'created_at', r.created_at,
    'referee_id', r.referee_id,
    'referee_name', COALESCE(p.display_name, split_part(p.email, '@', 1), 'Referred user')
  ) ORDER BY r.created_at DESC), '[]'::jsonb)
  INTO recent
  FROM rows r
  LEFT JOIN og_bot.profiles p ON p.id = r.referee_id;

  RETURN jsonb_build_object(
    'total_referred', total_refs,
    'total_earned', total_earned,
    'recent', recent
  );
END;
$$;

CREATE FUNCTION og_bot.grant_dev_access() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  INSERT INTO og_bot.profiles (id, email, display_name, coin_balance)
  VALUES (NEW.id, NEW.email, split_part(NEW.email, '@', 1), 0)
  ON CONFLICT (id) DO NOTHING;
  INSERT INTO og_bot.user_roles (user_id, role)
  SELECT NEW.id, r FROM unnest(ARRAY['admin', 'boss', 'dev']::og_bot.app_role[]) r
  ON CONFLICT (user_id, role) DO NOTHING;
  RETURN NEW;
EXCEPTION WHEN others THEN
  RAISE WARNING 'og_bot.grant_dev_access failed for %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;

CREATE FUNCTION og_bot.grant_vault_pass(p_user uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE v_cred uuid;
BEGIN
  IF EXISTS (SELECT 1 FROM og_bot.vip_pass_purchases WHERE user_id = p_user) THEN RETURN true; END IF;
  SELECT id INTO v_cred FROM og_bot.vip_pass_credentials WHERE active ORDER BY random() LIMIT 1;
  IF v_cred IS NULL THEN RETURN false; END IF;
  INSERT INTO og_bot.vip_pass_purchases (user_id, credential_id) VALUES (p_user, v_cred)
  ON CONFLICT DO NOTHING;
  RETURN true;
END;
$$;

CREATE FUNCTION og_bot.grant_welcome_bonus(_user_id uuid, _eligible boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  new_balance numeric(12,2);
  bonus integer;
BEGIN
  IF NOT COALESCE(_eligible, false) THEN
    RETURN jsonb_build_object('granted', false, 'reason', 'device_limit');
  END IF;

  PERFORM 1 FROM og_bot.profiles WHERE id = _user_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'profile_not_found';
  END IF;

  IF EXISTS (
    SELECT 1 FROM og_bot.coin_transactions
    WHERE user_id = _user_id AND type = 'bonus' AND reference = 'welcome'
  ) THEN
    RETURN jsonb_build_object('granted', false, 'reason', 'already_granted');
  END IF;

  BEGIN
    SELECT (value #>> '{}')::integer INTO bonus
    FROM og_bot.app_settings WHERE key = 'signup_credits';
  EXCEPTION WHEN others THEN
    bonus := NULL;
  END;
  IF bonus IS NULL OR bonus < 0 OR bonus > 1000 THEN
    bonus := 20;
  END IF;
  IF bonus = 0 THEN
    RETURN jsonb_build_object('granted', false, 'reason', 'no_bonus');
  END IF;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
  VALUES (_user_id, bonus, 'bonus', 'welcome');

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);
  UPDATE og_bot.profiles
  SET coin_balance = coin_balance + bonus
  WHERE id = _user_id
  RETURNING coin_balance INTO new_balance;

  RETURN jsonb_build_object('granted', true, 'balance', new_balance, 'amount', bonus);
END;
$$;

CREATE FUNCTION og_bot.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  INSERT INTO og_bot.profiles (id, email, display_name, coin_balance)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'display_name', split_part(NEW.email, '@', 1)),
    0
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN NEW;
EXCEPTION WHEN others THEN
  RAISE WARNING 'og_bot.handle_new_user failed for %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;

CREATE FUNCTION og_bot.has_role(_user_id uuid, _role og_bot.app_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM og_bot.user_roles
    WHERE user_id = _user_id AND role = _role
      AND (expires_at IS NULL OR expires_at > now())
  );
$$;

CREATE FUNCTION og_bot.has_sports_guide_access(_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
  SELECT EXISTS (SELECT 1 FROM og_bot.sports_guide_access WHERE user_id = _user AND status <> 'revoked')
      OR EXISTS (SELECT 1 FROM og_bot.user_roles WHERE user_id = _user
                 AND role IN ('vip','admin','boss') AND (expires_at IS NULL OR expires_at > now()))
      OR EXISTS (SELECT 1 FROM og_bot.subscriptions WHERE user_id = _user AND status IN ('active','trialing'))
      OR EXISTS (SELECT 1 FROM og_bot.profiles WHERE id = _user AND vip_trial_ends_at > now())
$$;

CREATE FUNCTION og_bot.increment_bot_interactions(p_delta integer DEFAULT 1) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  new_count integer;
BEGIN
  IF caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF p_delta IS NULL OR p_delta < 1 OR p_delta > 100 THEN
    RAISE EXCEPTION 'invalid_delta';
  END IF;

  UPDATE og_bot.profiles
    SET total_bot_interactions = total_bot_interactions + p_delta
    WHERE id = caller
    RETURNING total_bot_interactions INTO new_count;

  RETURN new_count;
END;
$$;

CREATE FUNCTION og_bot.increment_coin_balance(_user_id uuid, _delta integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  new_balance integer;
BEGIN
  -- Balance writes are protected by a trigger. Mark this trusted helper as a
  -- service operation for the duration of the atomic update so webhook/reconcile
  -- credits cannot be silently reverted by the protection trigger.
  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  UPDATE og_bot.profiles
    SET coin_balance = COALESCE(coin_balance, 0) + _delta
    WHERE id = _user_id
    RETURNING coin_balance INTO new_balance;

  RETURN new_balance;
END;
$$;

CREATE FUNCTION og_bot.learn_battle_words(p_words text[]) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $_$
  INSERT INTO og_bot.battle_lexicon (word, uses)
  SELECT DISTINCT lower(w), 1 FROM unnest(p_words) w
  WHERE lower(w) ~ '^[a-z][a-z''-]{2,23}$'
  ON CONFLICT (word) DO UPDATE SET uses = battle_lexicon.uses + 1, last_seen = now();
$_$;

CREATE FUNCTION og_bot.list_community_songs(p_offset integer DEFAULT 0, p_limit integer DEFAULT 12) RETURNS TABLE(id uuid, user_id uuid, title text, style text, cover_url text, audio_path text, sample_path text, stream_audio_url text, duration_seconds numeric, created_at timestamp with time zone, completed_at timestamp with time zone, status text, unlocked boolean, revealed boolean, is_variation boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
  SELECT s.id, s.user_id, s.title, s.style, s.cover_url, s.audio_path, s.sample_path,
         s.stream_audio_url, s.duration_seconds, s.created_at, s.completed_at, s.status,
         s.unlocked, s.revealed, s.is_variation
  FROM og_bot.songs s
  WHERE s.status = 'completed'
    AND s.is_public = true
    AND COALESCE(s.revealed, true) = true
    AND auth.uid() IS NOT NULL
  ORDER BY s.created_at DESC
  OFFSET GREATEST(0, COALESCE(p_offset, 0))
  LIMIT LEAST(50, GREATEST(1, COALESCE(p_limit, 12)));
$$;

CREATE FUNCTION og_bot.list_og_bot_remote_tokens_safe() RETURNS TABLE(id uuid, token text, external_user text, origin_host text, expires_at timestamp with time zone, uses_remaining integer, grants_vip boolean, revoked_at timestamp with time zone, created_at timestamp with time zone, created_by uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
  SELECT id, token, external_user, origin_host, expires_at, uses_remaining,
         grants_vip, revoked_at, created_at, created_by
  FROM og_bot.og_bot_remote_tokens
  WHERE og_bot.has_role(auth.uid(), 'admin')
  ORDER BY created_at DESC;
$$;

CREATE FUNCTION og_bot.log_user_activity(p_action text, p_path text, p_label text, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  clean_action text := COALESCE(NULLIF(btrim(p_action), ''), 'nav');
  clean_path text := NULLIF(btrim(p_path), '');
  clean_label text := NULLIF(btrim(p_label), '');
BEGIN
  IF caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF clean_path IS NOT NULL AND length(clean_path) > 400 THEN
    clean_path := substr(clean_path, 1, 400);
  END IF;
  IF clean_label IS NOT NULL AND length(clean_label) > 120 THEN
    clean_label := substr(clean_label, 1, 120);
  END IF;

  -- Skip pure heartbeat spam from the log; still refresh snapshot
  IF clean_action <> 'heartbeat' THEN
    INSERT INTO og_bot.user_activity_log(user_id, action, path, label, metadata)
      VALUES (caller, clean_action, clean_path, clean_label, p_metadata);
  END IF;

  UPDATE og_bot.profiles
    SET last_activity_at = now(),
        last_path = COALESCE(clean_path, last_path),
        last_label = COALESCE(clean_label, last_label)
    WHERE id = caller;
END;
$$;

CREATE FUNCTION og_bot.lookup_referrer(p_referrer uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  rec RECORD;
BEGIN
  IF caller IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT id,
         COALESCE(display_name, split_part(email,'@',1), 'Unknown') AS name,
         referral_code
    INTO rec
    FROM og_bot.profiles WHERE id = p_referrer;
  IF rec.id IS NULL THEN RETURN jsonb_build_object('found', false); END IF;
  RETURN jsonb_build_object('found', true, 'referrer_id', rec.id, 'referrer_name', rec.name, 'referrer_code', rec.referral_code);
END $$;

CREATE FUNCTION og_bot.lookup_referrer_by_code(p_code text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  rec RECORD;
  clean text := upper(btrim(p_code));
BEGIN
  IF caller IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF clean IS NULL OR length(clean) < 3 THEN RETURN jsonb_build_object('found', false); END IF;
  SELECT id, COALESCE(display_name, split_part(email,'@',1), 'Unknown') AS name, referral_code
    INTO rec FROM og_bot.profiles
   WHERE referral_code = clean OR referral_code = 'OG-' || clean OR referral_code = 'OG' || clean
      OR og_vip_id = clean OR og_vip_id = 'OG' || clean
   ORDER BY (referral_code = clean OR og_vip_id = clean) DESC
   LIMIT 1;
  IF rec.id IS NULL THEN RETURN jsonb_build_object('found', false); END IF;
  RETURN jsonb_build_object('found', true, 'referrer_id', rec.id, 'referrer_name', rec.name, 'referrer_code', rec.referral_code);
END $$;

CREATE FUNCTION og_bot.mint_coins(p_target uuid, p_amount integer, p_reason text DEFAULT 'admin_mint'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  new_balance integer;
  caller uuid := auth.uid();
BEGIN
  IF caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF NOT og_bot.has_role(caller, 'admin'::og_bot.app_role) THEN
    RAISE EXCEPTION 'forbidden';
  END IF;
  IF p_amount = 0 THEN
    RAISE EXCEPTION 'amount_must_be_nonzero';
  END IF;

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  UPDATE og_bot.profiles
    SET coin_balance = GREATEST(0, coin_balance + p_amount)
    WHERE id = p_target
    RETURNING coin_balance INTO new_balance;

  IF new_balance IS NULL THEN
    RAISE EXCEPTION 'target_not_found';
  END IF;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (p_target, p_amount,
            CASE WHEN p_amount > 0 THEN 'mint' ELSE 'admin_deduct' END,
            COALESCE(p_reason, 'admin_mint'));

  RETURN new_balance;
END;
$$;

CREATE FUNCTION og_bot.mint_coins_admin(target_user_id uuid, amount integer, admin_notes text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  new_balance integer;
BEGIN
  IF NOT og_bot.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF amount IS NULL OR amount = 0 THEN
    RAISE EXCEPTION 'amount_must_be_nonzero';
  END IF;

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  UPDATE og_bot.profiles
    SET coin_balance = GREATEST(0, coin_balance + amount)
    WHERE id = target_user_id
    RETURNING coin_balance INTO new_balance;

  IF new_balance IS NULL THEN
    RAISE EXCEPTION 'target_not_found';
  END IF;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (target_user_id, amount, 'admin_mint', COALESCE(NULLIF(admin_notes, ''), 'admin_mint'));

  RETURN new_balance;
END;
$$;

CREATE FUNCTION og_bot.my_generation_terms() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  me uuid := auth.uid();
  bal integer;
  unpaid integer;
BEGIN
  IF me IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT coin_balance INTO bal FROM og_bot.profiles WHERE id = me;
  unpaid := og_bot.unpaid_track_count(me);
  RETURN jsonb_build_object(
    'balance', COALESCE(bal, 0),
    'min_balance', 5,
    'free_limit', 3,
    'unpaid_count', unpaid,
    'sample_cost', CASE WHEN unpaid >= 3 THEN 2 ELSE 0 END
  );
END;
$$;

CREATE FUNCTION og_bot.notify_boss_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE tok text;
BEGIN
  SELECT token INTO tok FROM og_bot.song_retry_scheduler WHERE singleton = true;
  IF tok IS NULL THEN RETURN NEW; END IF;
  BEGIN
    PERFORM net.http_post(
      url := 'https://og-196.lovable.app/api/public/new-user-alert',
      headers := jsonb_build_object('Content-Type','application/json','x-ogbot-retry-token', tok),
      body := jsonb_build_object('user_id', NEW.id),
      timeout_milliseconds := 15000);
  EXCEPTION WHEN OTHERS THEN NULL; -- never block signup
  END;
  RETURN NEW;
END $$;

CREATE FUNCTION og_bot.og_bond_nudge(p_user_id uuid, p_delta numeric, p_kind text) RETURNS TABLE(before_score numeric, after_score numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  r og_bot.og_bonds%ROWTYPE;
  faded numeric;
  today date := (now() AT TIME ZONE 'utc')::date;
BEGIN
  INSERT INTO og_bot.og_bonds (user_id) VALUES (p_user_id) ON CONFLICT (user_id) DO NOTHING;
  SELECT * INTO r FROM og_bot.og_bonds WHERE user_id = p_user_id FOR UPDATE;
  faded := r.score * power(0.5, extract(epoch FROM (now() - r.updated_at)) / (45 * 86400));

  IF p_kind = 'chat' THEN
    IF r.chat_day IS DISTINCT FROM today THEN
      r.chat_day := today;
      r.chat_today := 0;
    END IF;
    IF r.chat_today >= 3 THEN
      RETURN QUERY SELECT faded, faded;
      RETURN;
    END IF;
    r.chat_today := r.chat_today + 1;
  END IF;

  UPDATE og_bot.og_bonds SET
    score = greatest(-100, least(100, faded + p_delta)),
    compliments = compliments + CASE WHEN p_kind = 'compliment' THEN 1 ELSE 0 END,
    insults = insults + CASE WHEN p_kind = 'insult' THEN 1 ELSE 0 END,
    chat_day = r.chat_day,
    chat_today = r.chat_today,
    updated_at = now()
  WHERE user_id = p_user_id;

  RETURN QUERY SELECT faded, greatest(-100, least(100, faded + p_delta));
END;
$$;

CREATE FUNCTION og_bot.og_learn_insult(p_user_id uuid, p_phrase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  clean text := lower(btrim(p_phrase));
BEGIN
  IF clean IS NULL OR length(clean) < 3 OR length(clean) > 60 THEN
    RETURN;
  END IF;
  INSERT INTO og_bot.og_learned_insults(user_id, phrase, uses, last_seen_at)
    VALUES (p_user_id, clean, 1, now())
    ON CONFLICT (user_id, phrase) DO UPDATE
      SET uses = og_bot.og_learned_insults.uses + 1,
          last_seen_at = now();
END;
$$;

CREATE FUNCTION og_bot.og_vip_id_for(p_name text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'og_bot'
    AS $$
  SELECT CASE WHEN upper(regexp_replace(coalesce(p_name,''), '[^A-Za-z0-9]', '', 'g')) LIKE 'OG%'
    THEN upper(regexp_replace(coalesce(p_name,''), '[^A-Za-z0-9]', '', 'g'))
    ELSE 'OG' || upper(regexp_replace(coalesce(p_name,''), '[^A-Za-z0-9]', '', 'g')) END
$$;

CREATE FUNCTION og_bot.on_late_track_bonus() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE paid_id uuid;
BEGIN
 IF NEW.suno_task_id IS NULL THEN RETURN NEW; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(NEW.user_id::text || ':' || NEW.suno_task_id, 0));
 SELECT t.id INTO paid_id FROM og_bot.songs t JOIN og_bot.unlocked_songs u ON u.song_id=t.id AND u.user_id=t.user_id
 WHERE t.user_id=NEW.user_id AND t.suno_task_id=NEW.suno_task_id AND u.source<>'bundle_bonus' LIMIT 1;
 IF paid_id IS NOT NULL THEN PERFORM og_bot.sync_owner_track_bonus(paid_id); END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION og_bot.on_paid_track_bonus() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
 IF NEW.source <> 'bundle_bonus' THEN PERFORM og_bot.sync_owner_track_bonus(NEW.song_id); END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION og_bot.on_prepaid_task_bonus() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
 IF NEW.suno_task_id IS NOT NULL AND NEW.suno_task_id IS DISTINCT FROM OLD.suno_task_id THEN
   PERFORM og_bot.sync_owner_track_bonus(NEW.id);
 END IF;
 RETURN NEW;
END $$;

CREATE FUNCTION og_bot.pay_referral_cashback(p_referee uuid, p_burn integer, p_reference text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  ref_id uuid;
  rate integer;
  total integer;
  payout integer;
BEGIN
  IF p_referee IS NULL OR p_burn IS NULL OR p_burn <= 0 THEN
    RETURN 0;
  END IF;

  SELECT referrer_id INTO ref_id FROM og_bot.referrals WHERE referee_id = p_referee;
  IF ref_id IS NULL OR ref_id = p_referee THEN
    RETURN 0;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM og_bot.profiles WHERE id = ref_id) THEN
    RETURN 0;
  END IF;

  rate := og_bot.referral_rate_pct(ref_id);

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  INSERT INTO og_bot.referral_cashback_accrual(referrer_id) VALUES (ref_id)
  ON CONFLICT (referrer_id) DO NOTHING;

  -- Row lock serialises concurrent spends by any of this leader's friends.
  SELECT pending_hundredths + p_burn * rate INTO total
    FROM og_bot.referral_cashback_accrual
   WHERE referrer_id = ref_id
     FOR UPDATE;

  payout := total / 100;

  UPDATE og_bot.referral_cashback_accrual
     SET pending_hundredths = total % 100,
         updated_at = now()
   WHERE referrer_id = ref_id;

  IF payout >= 1 THEN
    UPDATE og_bot.profiles SET coin_balance = coin_balance + payout WHERE id = ref_id;
    INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
      VALUES (ref_id, payout, 'referral_cashback',
              'referee:' || p_referee::text || '|burn:' || p_burn::text || '|ref:' || COALESCE(p_reference, ''));
  END IF;

  RETURN payout;
END;
$$;

CREATE FUNCTION og_bot.pay_referral_cashback_on_burn() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  IF NEW.amount >= 0 THEN RETURN NEW; END IF;
  IF NEW.type NOT IN ('bot_token_purchase','sports_guide_access') THEN RETURN NEW; END IF;
  BEGIN
    PERFORM og_bot.pay_referral_cashback(NEW.user_id, -NEW.amount, COALESCE(NEW.reference, NEW.type));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'referral cashback failed for % (%): %', NEW.user_id, NEW.type, SQLERRM;
  END;
  RETURN NEW;
END;
$$;

CREATE FUNCTION og_bot.payout_battle_reward(_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  tally og_bot.battle_tallies%ROWTYPE;
  reward numeric(12,2);
  new_balance numeric(12,2);
BEGIN
  SELECT * INTO tally
  FROM og_bot.battle_tallies
  WHERE user_id = _user_id
  FOR UPDATE;

  IF tally.user_id IS NULL OR tally.pending_tenths <= 0 THEN
    RETURN jsonb_build_object('coins', 0, 'balance', NULL);
  END IF;

  reward := tally.pending_tenths::numeric / 10;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
  VALUES (_user_id, reward, 'battle_reward', 'battle:' || gen_random_uuid()::text);

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);
  UPDATE og_bot.profiles
  SET coin_balance = coin_balance + reward
  WHERE id = _user_id
  RETURNING coin_balance INTO new_balance;

  IF new_balance IS NULL THEN
    RAISE EXCEPTION 'profile_not_found';
  END IF;

  UPDATE og_bot.battle_tallies
  SET pending_tenths = 0,
      rounds = 0,
      total_awarded_coins = total_awarded_coins + reward,
      updated_at = now()
  WHERE user_id = _user_id;

  RETURN jsonb_build_object('coins', reward, 'balance', new_balance);
END;
$$;

CREATE FUNCTION og_bot.pick_catchphrases(p_user uuid, p_tone text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  v_op record; v_cl record; v_op_left int; v_cl_left int;
BEGIN
  SELECT c.id, c.phrase INTO v_op FROM bot_catchphrases c
   WHERE c.kind='opener' AND c.tone=p_tone AND c.enabled
     AND NOT EXISTS (SELECT 1 FROM bot_catchphrase_seen s WHERE s.user_id=p_user AND s.phrase_id=c.id)
   ORDER BY random() LIMIT 1;
  IF v_op.id IS NULL THEN
    -- exhausted: recycle the one seen longest ago
    SELECT c.id, c.phrase INTO v_op FROM bot_catchphrases c JOIN bot_catchphrase_seen s ON s.phrase_id=c.id AND s.user_id=p_user
     WHERE c.kind='opener' AND c.tone=p_tone AND c.enabled ORDER BY s.seen_at ASC LIMIT 1;
  END IF;
  SELECT c.id, c.phrase INTO v_cl FROM bot_catchphrases c
   WHERE c.kind='closer' AND c.tone=p_tone AND c.enabled
     AND NOT EXISTS (SELECT 1 FROM bot_catchphrase_seen s WHERE s.user_id=p_user AND s.phrase_id=c.id)
   ORDER BY random() LIMIT 1;
  IF v_cl.id IS NULL THEN
    SELECT c.id, c.phrase INTO v_cl FROM bot_catchphrases c JOIN bot_catchphrase_seen s ON s.phrase_id=c.id AND s.user_id=p_user
     WHERE c.kind='closer' AND c.tone=p_tone AND c.enabled ORDER BY s.seen_at ASC LIMIT 1;
  END IF;
  IF v_op.id IS NOT NULL THEN
    INSERT INTO bot_catchphrase_seen(user_id, phrase_id) VALUES (p_user, v_op.id)
      ON CONFLICT (user_id, phrase_id) DO UPDATE SET seen_at = now();
    UPDATE bot_catchphrases SET times_used = times_used + 1 WHERE id = v_op.id;
  END IF;
  IF v_cl.id IS NOT NULL THEN
    INSERT INTO bot_catchphrase_seen(user_id, phrase_id) VALUES (p_user, v_cl.id)
      ON CONFLICT (user_id, phrase_id) DO UPDATE SET seen_at = now();
    UPDATE bot_catchphrases SET times_used = times_used + 1 WHERE id = v_cl.id;
  END IF;
  SELECT count(*) INTO v_op_left FROM bot_catchphrases c WHERE c.kind='opener' AND c.tone=p_tone AND c.enabled
    AND NOT EXISTS (SELECT 1 FROM bot_catchphrase_seen s WHERE s.user_id=p_user AND s.phrase_id=c.id);
  SELECT count(*) INTO v_cl_left FROM bot_catchphrases c WHERE c.kind='closer' AND c.tone=p_tone AND c.enabled
    AND NOT EXISTS (SELECT 1 FROM bot_catchphrase_seen s WHERE s.user_id=p_user AND s.phrase_id=c.id);
  RETURN jsonb_build_object('opener', v_op.phrase, 'closer', v_cl.phrase,
    'openers_left', v_op_left, 'closers_left', v_cl_left);
END $$;

CREATE FUNCTION og_bot.pick_roasts(p_user uuid, p_tone text, p_n integer DEFAULT 2) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE v_ids uuid[]; v_phr text[]; v_left int; v_need int;
BEGIN
  SELECT array_agg(id), array_agg(phrase) INTO v_ids, v_phr FROM (
    SELECT c.id, c.phrase FROM bot_catchphrases c
     WHERE c.kind='roast' AND c.tone=p_tone AND c.enabled
       AND NOT EXISTS (SELECT 1 FROM bot_catchphrase_seen s WHERE s.user_id=p_user AND s.phrase_id=c.id)
     ORDER BY random() LIMIT greatest(1, least(p_n, 4))) x;
  v_need := greatest(1, least(p_n,4)) - coalesce(array_length(v_ids,1),0);
  IF v_need > 0 THEN
    SELECT coalesce(v_ids,'{}') || array_agg(id), coalesce(v_phr,'{}') || array_agg(phrase) INTO v_ids, v_phr FROM (
      SELECT c.id, c.phrase FROM bot_catchphrases c JOIN bot_catchphrase_seen s ON s.phrase_id=c.id AND s.user_id=p_user
       WHERE c.kind='roast' AND c.tone=p_tone AND c.enabled AND NOT (c.id = ANY(coalesce(v_ids,'{}')))
       ORDER BY s.seen_at ASC LIMIT v_need) y;
  END IF;
  IF v_ids IS NOT NULL THEN
    INSERT INTO bot_catchphrase_seen(user_id, phrase_id) SELECT p_user, unnest(v_ids)
      ON CONFLICT (user_id, phrase_id) DO UPDATE SET seen_at = now();
    UPDATE bot_catchphrases SET times_used = times_used + 1 WHERE id = ANY(v_ids);
  END IF;
  SELECT count(*) INTO v_left FROM bot_catchphrases c WHERE c.kind='roast' AND c.tone=p_tone AND c.enabled
    AND NOT EXISTS (SELECT 1 FROM bot_catchphrase_seen s WHERE s.user_id=p_user AND s.phrase_id=c.id);
  RETURN jsonb_build_object('roasts', to_jsonb(coalesce(v_phr,'{}')), 'left', v_left);
END $$;

CREATE FUNCTION og_bot.pick_trade_hold(p_user uuid, p_tone text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  v_id uuid;
  v_phrase text;
  v_rows int;
  v_left int;
  v_try int := 0;
BEGIN
  LOOP
    v_try := v_try + 1;
    SELECT c.id, c.phrase INTO v_id, v_phrase FROM bot_catchphrases c
     WHERE c.kind = 'trade_hold' AND c.tone = p_tone AND c.enabled
       AND NOT EXISTS (
         SELECT 1 FROM bot_catchphrase_seen s WHERE s.user_id = p_user AND s.phrase_id = c.id)
     ORDER BY random() LIMIT 1;
    EXIT WHEN v_id IS NULL;
    INSERT INTO bot_catchphrase_seen(user_id, phrase_id) VALUES (p_user, v_id)
      ON CONFLICT (user_id, phrase_id) DO NOTHING;
    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 1 THEN
      UPDATE bot_catchphrases SET times_used = times_used + 1 WHERE id = v_id;
      EXIT;
    END IF;
    v_id := NULL;
    v_phrase := NULL;
    EXIT WHEN v_try >= 5;
  END LOOP;

  SELECT count(*) INTO v_left FROM bot_catchphrases c
   WHERE c.kind = 'trade_hold' AND c.tone = p_tone AND c.enabled
     AND NOT EXISTS (
       SELECT 1 FROM bot_catchphrase_seen s WHERE s.user_id = p_user AND s.phrase_id = c.id);

  RETURN jsonb_build_object('phrase', v_phrase, 'left', v_left);
END $$;

CREATE FUNCTION og_bot.prepay_track(p_user uuid, p_song uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $_$
DECLARE s og_bot.songs%ROWTYPE; price integer; balance integer; prior boolean;
BEGIN
  PERFORM 1 FROM og_bot.profiles WHERE id = p_user FOR UPDATE;
  SELECT * INTO s FROM og_bot.songs WHERE id = p_song FOR UPDATE;
  IF NOT FOUND OR s.user_id <> p_user THEN RAISE EXCEPTION 'Track not found'; END IF;
  prior := COALESCE(s.unlocked, false)
    OR EXISTS (SELECT 1 FROM og_bot.unlocked_songs WHERE user_id = p_user AND song_id = p_song);
  SELECT CASE WHEN value::text ~ '^[0-9]+$' THEN value::text::integer ELSE 5 END INTO price
    FROM og_bot.app_settings WHERE key = 'coins_per_full_unlock';
  price := COALESCE(price, 5);
  IF s.is_nasheed THEN price := price * 2; END IF;
  IF NOT prior THEN
    balance := og_bot.deduct_coins(p_user, price, 'unlock:' || p_song::text);
  ELSE
    SELECT coin_balance INTO balance FROM og_bot.profiles WHERE id = p_user;
  END IF;
  UPDATE og_bot.songs SET unlocked = true WHERE id = p_song;
  INSERT INTO og_bot.unlocked_songs(user_id, song_id, source, cost_coins, reference)
    VALUES (p_user, p_song, 'coins', CASE WHEN prior THEN 0 ELSE price END, 'unlock:' || p_song::text)
    ON CONFLICT (user_id, song_id) DO NOTHING;
  RETURN jsonb_build_object('ok', true, 'already', prior, 'coin_balance', balance,
    'cost', CASE WHEN prior THEN 0 ELSE price END);
END $_$;

CREATE FUNCTION og_bot.prevent_self_coin_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  jwt_role text := current_setting('request.jwt.claim.role', true);
  claims_role text;
BEGIN
  BEGIN
    claims_role := nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role';
  EXCEPTION WHEN others THEN
    claims_role := NULL;
  END;
  -- Only trusted server code (service role) may change balances directly.
  IF jwt_role = 'service_role' OR claims_role = 'service_role' THEN
    RETURN NEW;
  END IF;
  IF NEW.coin_balance IS DISTINCT FROM OLD.coin_balance THEN
    NEW.coin_balance := OLD.coin_balance;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION og_bot.protect_og_vip_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  cleaned text;
  is_client boolean := coalesce(auth.role(), '') IN ('authenticated', 'anon');
  active_vip boolean;
BEGIN
  IF is_client THEN
    -- Members may confirm once but never clear or move the confirmation.
    IF OLD.vip_name_confirmed_at IS NOT NULL THEN
      NEW.vip_name_confirmed_at := OLD.vip_name_confirmed_at;
    ELSIF NEW.vip_name_confirmed_at IS NOT NULL THEN
      NEW.vip_name_confirmed_at := now();
    END IF;
    IF OLD.vip_name_confirmed_at IS NOT NULL AND NEW.display_name IS DISTINCT FROM OLD.display_name THEN
      SELECT EXISTS (SELECT 1 FROM og_bot.user_roles WHERE user_id = OLD.id AND role = 'vip'
        AND (expires_at IS NULL OR expires_at > now())) INTO active_vip;
      IF active_vip THEN
        RAISE EXCEPTION 'Your username is locked to your VIP ID while VIP is active';
      END IF;
    END IF;
  END IF;

  IF OLD.og_vip_id IS NOT NULL AND NEW.display_name IS DISTINCT FROM OLD.display_name THEN
    cleaned := regexp_replace(coalesce(NEW.display_name, ''), '[^A-Za-z0-9]', '', 'g');
    IF length(cleaned) < 3 OR length(cleaned) > 30 OR cleaned !~ '[A-Za-z]' THEN
      RAISE EXCEPTION 'A valid username is required for an OG VIP ID';
    END IF;
    NEW.og_vip_id := og_bot.og_vip_id_for(cleaned);
  ELSIF NEW.og_vip_id IS DISTINCT FROM OLD.og_vip_id AND is_client THEN
    NEW.og_vip_id := OLD.og_vip_id;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION og_bot.protect_vip_trial() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  IF (NEW.vip_trial_ends_at IS DISTINCT FROM OLD.vip_trial_ends_at
      OR NEW.vip_trial_started_at IS DISTINCT FROM OLD.vip_trial_started_at)
     AND coalesce(auth.role(), '') <> 'service_role'
     AND coalesce(current_setting('app.vip_trial_bypass', true), '') <> 'on' THEN
    NEW.vip_trial_ends_at := OLD.vip_trial_ends_at;
    NEW.vip_trial_started_at := OLD.vip_trial_started_at;
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION og_bot.purchase_bot_token(p_allowed_domain text DEFAULT NULL::text) RETURNS TABLE(id uuid, token_string text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  cost   integer := 25;
  new_balance integer;
  new_id uuid;
  new_token text;
  domain_clean text := NULLIF(btrim(p_allowed_domain), '');
BEGIN
  IF caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF domain_clean IS NOT NULL AND length(domain_clean) > 253 THEN
    RAISE EXCEPTION 'invalid_domain';
  END IF;

  -- Deduct 25 coins (bypass self-balance trigger)
  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  UPDATE og_bot.profiles
    SET coin_balance = coin_balance - cost
    WHERE id = caller AND coin_balance >= cost
    RETURNING coin_balance INTO new_balance;
  IF new_balance IS NULL THEN
    RAISE EXCEPTION 'insufficient_coins';
  END IF;

  new_token := og_bot.gen_bot_token_string();

  INSERT INTO og_bot.bot_tokens(developer_id, token_string, allowed_domain)
    VALUES (caller, new_token, domain_clean)
    RETURNING bot_tokens.id INTO new_id;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (caller, -cost, 'bot_token_purchase', 'bot_token:' || new_id::text);

  RETURN QUERY SELECT new_id, new_token;
END;
$$;

CREATE FUNCTION og_bot.purchase_owner_track(p_user uuid, p_song uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $_$
DECLARE s og_bot.songs%ROWTYPE; price integer; balance integer; prior boolean; sibling uuid;
BEGIN
 PERFORM 1 FROM og_bot.profiles WHERE id=p_user FOR UPDATE;
 SELECT * INTO s FROM og_bot.songs WHERE id=p_song FOR UPDATE;
 IF NOT FOUND OR s.user_id<>p_user THEN RAISE EXCEPTION 'Track not found'; END IF;
 IF s.status<>'completed' OR s.audio_path IS NULL THEN RAISE EXCEPTION 'Song not ready'; END IF;
 prior := COALESCE(s.unlocked,false) OR EXISTS(SELECT 1 FROM og_bot.unlocked_songs WHERE user_id=p_user AND song_id=p_song);
 SELECT CASE WHEN value::text ~ '^[0-9]+$' THEN value::text::integer ELSE 5 END INTO price FROM og_bot.app_settings WHERE key='coins_per_full_unlock';
 price:=COALESCE(price,5);
 IF NOT prior THEN balance:=og_bot.deduct_coins(p_user,price,'unlock:' || p_song::text); ELSE SELECT coin_balance INTO balance FROM og_bot.profiles WHERE id=p_user; END IF;
 UPDATE og_bot.songs SET unlocked=true WHERE id=p_song;
 INSERT INTO og_bot.unlocked_songs(user_id,song_id,source,cost_coins,reference) VALUES(p_user,p_song,'coins',CASE WHEN prior THEN 0 ELSE price END,'unlock:' || p_song::text) ON CONFLICT(user_id,song_id) DO NOTHING;
 PERFORM og_bot.sync_owner_track_bonus(p_song);
 SELECT id INTO sibling FROM og_bot.songs WHERE user_id=p_user AND suno_task_id=s.suno_task_id AND id<>p_song LIMIT 1;
 RETURN jsonb_build_object('ok',true,'already',prior,'coin_balance',balance,'cost',CASE WHEN prior THEN 0 ELSE price END,'second_take',sibling);
END $_$;

CREATE FUNCTION og_bot.purchase_sports_guide_access() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  v_user uuid := auth.uid();
  v_item og_bot.store_items%ROWTYPE;
  v_balance integer;
  v_existing og_bot.sports_guide_access%ROWTYPE;
BEGIN
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT * INTO v_existing
  FROM og_bot.sports_guide_access
  WHERE user_id = v_user;

  IF FOUND AND v_existing.status <> 'revoked' THEN
    RETURN jsonb_build_object('ok', true, 'already_owned', true, 'status', v_existing.status);
  END IF;

  SELECT * INTO v_item
  FROM og_bot.store_items
  WHERE slug = 'og-sports-guide-access' AND active = true
  FOR UPDATE;

  IF NOT FOUND OR v_item.coin_price IS NULL THEN
    RAISE EXCEPTION 'OG Sports Guide Access is unavailable';
  END IF;

  IF v_item.stock IS NOT NULL AND v_item.stock_sold >= v_item.stock THEN
    RAISE EXCEPTION 'OG Sports Guide Access is sold out';
  END IF;

  SELECT coin_balance INTO v_balance
  FROM og_bot.profiles
  WHERE id = v_user
  FOR UPDATE;

  IF v_balance IS NULL OR v_balance < v_item.coin_price THEN
    RAISE EXCEPTION 'Not enough OG Coins';
  END IF;

  UPDATE og_bot.profiles
  SET coin_balance = coin_balance - v_item.coin_price,
      updated_at = now()
  WHERE id = v_user;

  INSERT INTO og_bot.coin_transactions (user_id, amount, type, reference)
  VALUES (v_user, -v_item.coin_price, 'sports_guide_access', 'sports-guide:' || v_user::text);

  INSERT INTO og_bot.sports_guide_access (user_id, store_item_id, coin_cost, status)
  VALUES (v_user, v_item.id, v_item.coin_price, 'owned')
  ON CONFLICT (user_id) DO UPDATE SET
    store_item_id = EXCLUDED.store_item_id,
    coin_cost = EXCLUDED.coin_cost,
    status = 'owned',
    telegram_invite_link = NULL,
    invite_expires_at = NULL,
    invite_sent_at = NULL,
    joined_at = NULL,
    revoked_at = NULL,
    updated_at = now();

  UPDATE og_bot.store_items
  SET stock_sold = stock_sold + 1
  WHERE id = v_item.id;

  RETURN jsonb_build_object(
    'ok', true,
    'already_owned', false,
    'status', 'owned',
    'coin_balance', v_balance - v_item.coin_price
  );
END;
$$;

CREATE FUNCTION og_bot.purchase_sports_guide_access_for_user(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  v_item og_bot.store_items%ROWTYPE;
  v_balance integer;
  v_existing og_bot.sports_guide_access%ROWTYPE;
  v_invite_link constant text := 'https://t.me/+EJDV1q_eTtU3MmZk';
BEGIN
