  END IF;

  SELECT * INTO v_item
  FROM og_bot.store_items
  WHERE slug = 'og-sports-guide-access' AND active = true
  FOR UPDATE;

  IF NOT FOUND OR v_item.coin_price IS NULL THEN
    RAISE EXCEPTION 'OG Sports Guide Access is unavailable';
  END IF;

  IF v_item.stock IS NOT NULL AND v_item.stock_sold >= v_item.stock THEN
    RAISE EXCEPTION 'OG Sports Guide Access is sold out';
  END IF;

  SELECT coin_balance INTO v_balance
  FROM og_bot.profiles
  WHERE id = p_user
  FOR UPDATE;

  IF v_balance IS NULL OR v_balance < v_item.coin_price THEN
    RAISE EXCEPTION 'Not enough OG Coins';
  END IF;

  UPDATE og_bot.profiles
  SET coin_balance = coin_balance - v_item.coin_price,
      updated_at = now()
  WHERE id = p_user;

  INSERT INTO og_bot.coin_transactions (user_id, amount, type, reference)
  VALUES (p_user, -v_item.coin_price, 'sports_guide_access', 'sports-guide:' || p_user::text);

  INSERT INTO og_bot.sports_guide_access (user_id, store_item_id, coin_cost, status, telegram_invite_link)
  VALUES (p_user, v_item.id, v_item.coin_price, 'owned', v_invite_link)
  ON CONFLICT (user_id) DO UPDATE SET
    store_item_id = EXCLUDED.store_item_id,
    coin_cost = EXCLUDED.coin_cost,
    status = 'owned',
    telegram_invite_link = v_invite_link,
    invite_expires_at = NULL,
    invite_sent_at = NULL,
    joined_at = NULL,
    revoked_at = NULL,
    updated_at = now();

  UPDATE og_bot.store_items
  SET stock_sold = stock_sold + 1
  WHERE id = v_item.id;

  RETURN jsonb_build_object(
    'ok', true,
    'already_owned', false,
    'status', 'owned',
    'coin_balance', v_balance - v_item.coin_price
  );
END;
$$;

CREATE FUNCTION og_bot.purchase_vip() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  cost   integer := 20;
  new_balance integer;
BEGIN
  IF caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  IF EXISTS (SELECT 1 FROM og_bot.user_roles WHERE user_id = caller AND role = 'vip') THEN
    RAISE EXCEPTION 'already_vip';
  END IF;

  -- Bypass self-balance-protect trigger for this txn
  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  UPDATE og_bot.profiles
    SET coin_balance = coin_balance - cost
    WHERE id = caller AND coin_balance >= cost
    RETURNING coin_balance INTO new_balance;
  IF new_balance IS NULL THEN
    RAISE EXCEPTION 'insufficient_coins';
  END IF;

  INSERT INTO og_bot.user_roles(user_id, role) VALUES (caller, 'vip')
    ON CONFLICT (user_id, role) DO NOTHING;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (caller, -cost, 'vip_purchase', 'self_purchase_vip');

  RETURN new_balance;
END;
$$;

CREATE FUNCTION og_bot.purchase_vip_pass_for_user(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  v_price int;
  v_cred og_bot.vip_pass_credentials%ROWTYPE;
  v_balance int;
BEGIN
  IF auth.uid() IS NOT NULL AND auth.uid() <> p_user THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  SELECT c.* INTO v_cred
  FROM og_bot.vip_pass_purchases p
  JOIN og_bot.vip_pass_credentials c ON c.id = p.credential_id
  WHERE p.user_id = p_user;
  IF FOUND THEN
    RETURN jsonb_build_object('ok', true, 'already_owned', true,
      'username', v_cred.username, 'password', v_cred.password);
  END IF;

  SELECT coin_price INTO v_price FROM og_bot.store_items WHERE slug = 'og-vip-pass';
  v_price := COALESCE(v_price, 25);

  SELECT coin_balance INTO v_balance FROM og_bot.profiles WHERE id = p_user FOR UPDATE;
  IF v_balance IS NULL OR v_balance < v_price THEN
    RAISE EXCEPTION 'Not enough OG Coins';
  END IF;

  SELECT * INTO v_cred
  FROM og_bot.vip_pass_credentials
  WHERE active
  ORDER BY random()
  LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Sold out — no VIP passes available right now';
  END IF;

  UPDATE og_bot.profiles SET coin_balance = coin_balance - v_price WHERE id = p_user;
  INSERT INTO og_bot.coin_transactions (user_id, amount, type, reference)
  VALUES (p_user, -v_price, 'vip_pass', 'og-vip-pass');
  INSERT INTO og_bot.vip_pass_purchases (user_id, credential_id)
  VALUES (p_user, v_cred.id);

  RETURN jsonb_build_object('ok', true, 'already_owned', false,
    'username', v_cred.username, 'password', v_cred.password);
END;
$$;

CREATE FUNCTION og_bot.purge_expired_vip_roles() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE n integer;
BEGIN
  WITH d AS (
    DELETE FROM og_bot.user_roles WHERE role = 'vip' AND expires_at IS NOT NULL AND expires_at <= now()
    RETURNING user_id
  )
  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    SELECT user_id, 0, 'vip_revoke', 'vip_expired' FROM d;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END;
$$;

CREATE FUNCTION og_bot.redeem_og_bot_invite(p_code text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  caller uuid := auth.uid();
  inv RECORD;
  new_token text;
BEGIN
  IF caller IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  -- Lock the invite row to make the redemption race-safe.
  SELECT * INTO inv
    FROM og_bot.og_bot_token_invites
    WHERE code = btrim(p_code)
    FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'invite_not_found';
  END IF;
  IF inv.revoked_at IS NOT NULL THEN
    RAISE EXCEPTION 'invite_revoked';
  END IF;
  IF inv.redeemed_at IS NOT NULL THEN
    RAISE EXCEPTION 'invite_already_redeemed';
  END IF;
  IF inv.claim_expires_at IS NOT NULL AND inv.claim_expires_at < now() THEN
    RAISE EXCEPTION 'invite_expired';
  END IF;

  -- Grant og_bot role (no-op if already present).
  INSERT INTO og_bot.user_roles(user_id, role)
    VALUES (caller, 'og_bot')
    ON CONFLICT (user_id, role) DO NOTHING;

  -- Mint / refresh the caller's personal bot token using the invite's preset expiry.
  new_token := og_bot.gen_og_bot_token();
  INSERT INTO og_bot.og_bot_tokens(user_id, token, expires_at)
    VALUES (caller, new_token, inv.token_expires_at)
    ON CONFLICT (user_id) DO UPDATE
      SET token = EXCLUDED.token,
          expires_at = EXCLUDED.expires_at,
          updated_at = now(),
          last_used_at = NULL,
          revoked_at = NULL;

  UPDATE og_bot.og_bot_token_invites
    SET redeemed_by = caller, redeemed_at = now(), updated_at = now()
    WHERE id = inv.id;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (caller, 0, 'og_bot_invite_redeem', 'invite:' || inv.id::text);

  RETURN new_token;
END;
$$;

CREATE FUNCTION og_bot.referral_owed_hundredths() RETURNS TABLE(referrer_id uuid, net_burned bigint, rate_pct integer, owed_hundredths bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
  WITH charges AS (
    SELECT r.referrer_id, t.user_id, t.reference, -t.amount AS burned
      FROM og_bot.coin_transactions t
      JOIN og_bot.referrals r ON r.referee_id = t.user_id
     WHERE t.amount < 0
       AND t.type IN ('generation', 'bot_token_purchase', 'sports_guide_access')
       AND t.created_at >= r.created_at
       AND r.referrer_id <> t.user_id
  ),
  -- Each refund counted once, if it reverses one of the friend's charges.
  refunds AS (
    SELECT r.referrer_id, SUM(f.amount) AS refunded
      FROM og_bot.coin_transactions f
      JOIN og_bot.referrals r ON r.referee_id = f.user_id
     WHERE f.type = 'refund'
       AND f.amount > 0
       AND f.created_at >= r.created_at
       AND f.reference IS NOT NULL
       AND EXISTS (
         SELECT 1 FROM og_bot.coin_transactions c
          WHERE c.user_id = f.user_id
            AND c.amount < 0
            AND c.type IN ('generation', 'bot_token_purchase', 'sports_guide_access')
            AND c.reference IS NOT NULL
            AND c.created_at >= r.created_at
            AND (f.reference = c.reference OR f.reference = 'cancel:' || c.reference)
       )
     GROUP BY r.referrer_id
  ),
  per_leader AS (
    SELECT c.referrer_id, SUM(c.burned) AS burned
      FROM charges c
     GROUP BY c.referrer_id
  )
  SELECT p.referrer_id,
         GREATEST(0, p.burned - COALESCE(f.refunded, 0))::bigint AS net_burned,
         og_bot.referral_rate_pct(p.referrer_id) AS rate_pct,
         (GREATEST(0, p.burned - COALESCE(f.refunded, 0)) * og_bot.referral_rate_pct(p.referrer_id))::bigint
           AS owed_hundredths
    FROM per_leader p
    LEFT JOIN refunds f ON f.referrer_id = p.referrer_id
$$;

CREATE FUNCTION og_bot.referral_rate_pct(p_user uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
  SELECT CASE WHEN
    EXISTS (SELECT 1 FROM og_bot.user_roles WHERE user_id = p_user AND role IN ('vip','admin','boss')
            AND (expires_at IS NULL OR expires_at > now()))
    OR EXISTS (SELECT 1 FROM og_bot.subscriptions WHERE user_id = p_user AND status = 'active')
  THEN 13 ELSE 6 END
$$;

CREATE FUNCTION og_bot.refund_chat_image_edit(p_user uuid, p_free boolean, p_prev timestamp with time zone, p_reference text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  IF p_free THEN
    UPDATE chat_image_allowance SET last_free_at = p_prev, updated_at = now() WHERE user_id = p_user;
  ELSE
    PERFORM og_bot.refund_generation_charge(p_user, 1, p_reference);
  END IF;
END $$;

CREATE FUNCTION og_bot.refund_generation_charge(p_user uuid, p_amount integer, p_reference text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  new_balance integer;
BEGIN
  IF p_user IS NULL THEN
    RAISE EXCEPTION 'missing_user';
  END IF;
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'amount_must_be_positive';
  END IF;

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  UPDATE og_bot.profiles
    SET coin_balance = coin_balance + p_amount
    WHERE id = p_user
    RETURNING coin_balance INTO new_balance;

  IF new_balance IS NULL THEN
    RAISE EXCEPTION 'target_not_found';
  END IF;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (p_user, p_amount, 'refund', p_reference);

  RETURN new_balance;
END;
$$;

CREATE FUNCTION og_bot.regenerate_og_bot_token(target_user_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  new_token text;
BEGIN
  IF NOT og_bot.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM og_bot.user_roles WHERE user_id = target_user_id AND role = 'og_bot') THEN
    RAISE EXCEPTION 'not_og_bot';
  END IF;

  new_token := og_bot.gen_og_bot_token();

  INSERT INTO og_bot.og_bot_tokens(user_id, token)
    VALUES (target_user_id, new_token)
    ON CONFLICT (user_id) DO UPDATE
      SET token = EXCLUDED.token,
          updated_at = now(),
          last_used_at = NULL,
          revoked_at = NULL;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (target_user_id, 0, 'og_bot_token_rotate', 'admin_rotate_og_bot_token');

  RETURN new_token;
END;
$$;

CREATE FUNCTION og_bot.restore_instant_refund_clawback(_user_id uuid, _purchase_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  removed integer;
  bal integer;
BEGIN
  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  PERFORM 1 FROM og_bot.profiles WHERE id = _user_id FOR UPDATE;

  DELETE FROM og_bot.coin_transactions
   WHERE id = (
     SELECT id FROM og_bot.coin_transactions
      WHERE user_id = _user_id AND type = 'refund' AND reference = _purchase_reference
      ORDER BY created_at DESC
      LIMIT 1
   )
  RETURNING -amount INTO removed;

  IF removed IS NULL THEN
    SELECT coin_balance INTO bal FROM og_bot.profiles WHERE id = _user_id;
    RETURN jsonb_build_object('restored', false, 'balance', bal);
  END IF;

  UPDATE og_bot.profiles SET coin_balance = coin_balance + removed
   WHERE id = _user_id
  RETURNING coin_balance INTO bal;

  RETURN jsonb_build_object('restored', true, 'coins', removed, 'balance', bal);
END;
$$;

CREATE FUNCTION og_bot.reverse_referral_rewards_for_refund(_referee_id uuid, _env text, _session_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  r record;
  bal integer;
  take integer;
  inserted uuid;
  reversed integer := 0;
  coins_taken integer := 0;
  base text;
BEGIN
  IF _referee_id IS NULL OR _env IS NULL OR _session_id IS NULL OR length(trim(_session_id)) = 0 THEN
    RAISE EXCEPTION 'referee_env_session_required';
  END IF;

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  base := 'payment:referee:' || _referee_id::text || '|ref:stripe:' || _env || ':';

  -- Matches the references written by credit_payment_referral for each
  -- purchase kind the payments webhook rewards.
  FOR r IN
    SELECT user_id, amount, reference
      FROM og_bot.coin_transactions
     WHERE type = 'referral_payment'
       AND amount > 0
       AND reference IN (
         base || _session_id,
         base || 'vip:' || _session_id,
         base || 'track:' || _session_id,
         base || 'store:' || _session_id
       )
  LOOP
    SELECT coin_balance INTO bal FROM og_bot.profiles WHERE id = r.user_id FOR UPDATE;
    IF NOT FOUND THEN
      CONTINUE;
    END IF;
    take := LEAST(r.amount, GREATEST(COALESCE(bal, 0), 0));

    INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (r.user_id, -take, 'referral_payment_reversal', 'reversal:' || r.reference)
    ON CONFLICT (reference) WHERE type = 'referral_payment_reversal' AND reference IS NOT NULL
    DO NOTHING
    RETURNING id INTO inserted;

    IF inserted IS NOT NULL THEN
      IF take > 0 THEN
        UPDATE og_bot.profiles SET coin_balance = coin_balance - take WHERE id = r.user_id;
      END IF;
      reversed := reversed + 1;
      coins_taken := coins_taken + take;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('reversed', reversed, 'coins', coins_taken);
END;
$$;

CREATE FUNCTION og_bot.revoke_og_bot_invite(p_invite_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  IF NOT og_bot.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  UPDATE og_bot.og_bot_token_invites
    SET revoked_at = now(), updated_at = now()
    WHERE id = p_invite_id AND redeemed_at IS NULL AND revoked_at IS NULL;

  RETURN FOUND;
END;
$$;

CREATE FUNCTION og_bot.revoke_og_bot_token(target_user_id uuid, admin_notes text DEFAULT NULL::text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  ts timestamptz := now();
BEGIN
  IF NOT og_bot.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM og_bot.og_bot_tokens WHERE user_id = target_user_id) THEN
    RAISE EXCEPTION 'token_not_found';
  END IF;

  UPDATE og_bot.og_bot_tokens
    SET revoked_at = ts, updated_at = now()
    WHERE user_id = target_user_id;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (target_user_id, 0, 'og_bot_token_revoke',
            'admin_revoke_og_bot_token' || COALESCE(' | ' || NULLIF(btrim(admin_notes), ''), ''));

  RETURN ts;
END;
$$;

CREATE FUNCTION og_bot.set_balance_admin(target_user_id uuid, new_balance integer, admin_notes text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  old_balance integer;
  delta integer;
BEGIN
  IF NOT og_bot.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF new_balance IS NULL OR new_balance < 0 THEN
    RAISE EXCEPTION 'balance_out_of_range';
  END IF;

  SELECT coin_balance INTO old_balance FROM og_bot.profiles WHERE id = target_user_id;
  IF old_balance IS NULL THEN
    RAISE EXCEPTION 'target_not_found';
  END IF;

  delta := new_balance - old_balance;

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);
  UPDATE og_bot.profiles SET coin_balance = new_balance WHERE id = target_user_id;

  IF delta <> 0 THEN
    INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
      VALUES (target_user_id, delta,
              CASE WHEN delta > 0 THEN 'admin_mint' ELSE 'admin_deduct' END,
              COALESCE(NULLIF(admin_notes, ''), 'admin_set_balance'));
  END IF;

  RETURN new_balance;
END;
$$;

CREATE FUNCTION og_bot.set_boss_admin(target_user_id uuid, make_boss boolean, admin_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  IF NOT og_bot.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM og_bot.profiles WHERE id = target_user_id) THEN
    RAISE EXCEPTION 'target_not_found';
  END IF;
  IF make_boss THEN
    INSERT INTO og_bot.user_roles(user_id, role) VALUES (target_user_id, 'boss')
      ON CONFLICT (user_id, role) DO NOTHING;
    INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
      VALUES (target_user_id, 0, 'boss_grant',
              'admin_grant_boss' || COALESCE(' | ' || NULLIF(btrim(admin_notes), ''), ''));
    RETURN true;
  ELSE
    DELETE FROM og_bot.user_roles WHERE user_id = target_user_id AND role = 'boss';
    INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
      VALUES (target_user_id, 0, 'boss_revoke',
              'admin_revoke_boss' || COALESCE(' | ' || NULLIF(btrim(admin_notes), ''), ''));
    RETURN false;
  END IF;
END;
$$;

CREATE FUNCTION og_bot.set_dev_admin(target_user_id uuid, make_dev boolean, admin_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  IF NOT og_bot.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM og_bot.profiles WHERE id = target_user_id) THEN
    RAISE EXCEPTION 'target_not_found';
  END IF;
  IF make_dev THEN
    INSERT INTO og_bot.user_roles(user_id, role) VALUES (target_user_id, 'dev')
      ON CONFLICT (user_id, role) DO NOTHING;
    INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
      VALUES (target_user_id, 0, 'dev_grant',
              'admin_grant_dev' || COALESCE(' | ' || NULLIF(btrim(admin_notes), ''), ''));
    RETURN true;
  ELSE
    DELETE FROM og_bot.user_roles WHERE user_id = target_user_id AND role = 'dev';
    INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
      VALUES (target_user_id, 0, 'dev_revoke',
              'admin_revoke_dev' || COALESCE(' | ' || NULLIF(btrim(admin_notes), ''), ''));
    RETURN false;
  END IF;
END;
$$;

CREATE FUNCTION og_bot.set_og_bot_admin(target_user_id uuid, make_og boolean, admin_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  exists_already boolean;
BEGIN
  IF NOT og_bot.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM og_bot.profiles WHERE id = target_user_id) THEN
    RAISE EXCEPTION 'target_not_found';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM og_bot.user_roles WHERE user_id = target_user_id AND role = 'og_bot'
  ) INTO exists_already;

  IF make_og THEN
    IF NOT exists_already THEN
      INSERT INTO og_bot.user_roles(user_id, role) VALUES (target_user_id, 'og_bot')
        ON CONFLICT (user_id, role) DO NOTHING;
      INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
        VALUES (target_user_id, 0, 'og_bot_grant',
                'admin_grant_og_bot' || COALESCE(' | ' || NULLIF(btrim(admin_notes), ''), ''));
    END IF;
    INSERT INTO og_bot.og_bot_tokens(user_id, token)
      VALUES (target_user_id, og_bot.gen_og_bot_token())
      ON CONFLICT (user_id) DO NOTHING;
    RETURN true;
  ELSE
    IF exists_already THEN
      DELETE FROM og_bot.user_roles WHERE user_id = target_user_id AND role = 'og_bot';
      INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
        VALUES (target_user_id, 0, 'og_bot_revoke',
                'admin_revoke_og_bot' || COALESCE(' | ' || NULLIF(btrim(admin_notes), ''), ''));
    END IF;
    DELETE FROM og_bot.og_bot_tokens WHERE user_id = target_user_id;
    RETURN false;
  END IF;
END;
$$;

CREATE FUNCTION og_bot.set_og_bot_token_expiry(target_user_id uuid, new_expires_at timestamp with time zone, admin_notes text DEFAULT NULL::text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  old_expires timestamptz;
BEGIN
  IF NOT og_bot.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM og_bot.og_bot_tokens WHERE user_id = target_user_id) THEN
    RAISE EXCEPTION 'token_not_found';
  END IF;

  SELECT expires_at INTO old_expires FROM og_bot.og_bot_tokens WHERE user_id = target_user_id;

  UPDATE og_bot.og_bot_tokens
    SET expires_at = new_expires_at,
        updated_at = now()
    WHERE user_id = target_user_id;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (target_user_id, 0, 'og_bot_token_expiry',
            'expiry:' || COALESCE(old_expires::text, '∅') || '→' || COALESCE(new_expires_at::text, '∅')
            || COALESCE(' | ' || NULLIF(btrim(admin_notes), ''), ''));

  RETURN new_expires_at;
END;
$$;

CREATE FUNCTION og_bot.set_site_content(p_key text, p_value text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  trimmed_key text := btrim(p_key);
  trimmed_val text := p_value;
  prev_val text;
  cat text;
BEGIN
  IF NOT (og_bot.has_role(auth.uid(), 'admin') OR og_bot.has_role(auth.uid(), 'dev')) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF trimmed_key IS NULL OR length(trimmed_key) = 0 OR length(trimmed_key) > 200 THEN
    RAISE EXCEPTION 'invalid_key';
  END IF;
  IF trimmed_val IS NULL OR length(trimmed_val) > 5000 THEN
    RAISE EXCEPTION 'invalid_value';
  END IF;

  SELECT value INTO prev_val FROM og_bot.site_content WHERE key = trimmed_key;

  INSERT INTO og_bot.site_content(key, value, updated_by)
    VALUES (trimmed_key, trimmed_val, auth.uid())
    ON CONFLICT (key) DO UPDATE
      SET value = EXCLUDED.value, updated_at = now(), updated_by = auth.uid();

  IF prev_val IS DISTINCT FROM trimmed_val THEN
    cat := CASE
      WHEN trimmed_key LIKE 'og_persona.%' THEN 'persona'
      WHEN trimmed_key LIKE 'buyCoins.pack.%' THEN 'store'
      ELSE 'copy'
    END;
    INSERT INTO og_bot.boss_audit_log(actor_id, action, category, target_key, old_value, new_value)
      VALUES (auth.uid(),
              CASE WHEN prev_val IS NULL THEN 'create' ELSE 'update' END,
              cat, trimmed_key, prev_val, trimmed_val);
  END IF;

  RETURN trimmed_val;
END;
$$;

CREATE FUNCTION og_bot.set_telegram_worker(p_chat bigint, p_worker text, p_on boolean) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'og_bot'
    AS $$
DECLARE result jsonb;
BEGIN
 UPDATE og_bot.telegram_managed_groups SET active_workers = CASE WHEN p_on THEN CASE WHEN active_workers ? p_worker THEN active_workers ELSE active_workers || jsonb_build_array(p_worker) END ELSE active_workers - p_worker END, updated_at=now() WHERE chat_id=p_chat RETURNING active_workers INTO result;
 IF result IS NULL THEN RAISE EXCEPTION 'Group not found'; END IF;
 RETURN result;
END;
$$;

CREATE FUNCTION og_bot.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'og_bot'
    AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;

CREATE FUNCTION og_bot.set_updated_at_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

CREATE FUNCTION og_bot.set_vault_pass_admin(target_user_id uuid, grant_access boolean, admin_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  v_actor uuid := auth.uid();
  v_cred uuid;
BEGIN
  IF v_actor IS NULL OR NOT (og_bot.has_role(v_actor, 'boss') OR og_bot.has_role(v_actor, 'admin')) THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  IF grant_access THEN
    IF NOT EXISTS (SELECT 1 FROM og_bot.vip_pass_purchases WHERE user_id = target_user_id) THEN
      SELECT id INTO v_cred FROM og_bot.vip_pass_credentials WHERE active ORDER BY random() LIMIT 1;
      IF v_cred IS NULL THEN
        RAISE EXCEPTION 'no active vault credentials available';
      END IF;
      INSERT INTO og_bot.vip_pass_purchases (user_id, credential_id) VALUES (target_user_id, v_cred)
      ON CONFLICT DO NOTHING;
    END IF;
  ELSE
    DELETE FROM og_bot.vip_pass_purchases WHERE user_id = target_user_id;
  END IF;

  INSERT INTO og_bot.boss_audit_log (actor_id, action, category, target_key, old_value, new_value, metadata)
  VALUES (
    v_actor,
    CASE WHEN grant_access THEN 'vault_pass_grant' ELSE 'vault_pass_revoke' END,
    'vault_pass',
    target_user_id::text,
    NULL,
    admin_notes,
    jsonb_build_object('granted', grant_access)
  );

  RETURN grant_access;
END;
$$;

CREATE FUNCTION og_bot.set_vip_admin(target_user_id uuid, make_vip boolean, admin_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  exists_already boolean;
BEGIN
  IF NOT og_bot.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM og_bot.profiles WHERE id = target_user_id) THEN
    RAISE EXCEPTION 'target_not_found';
  END IF;

  SELECT EXISTS (
    SELECT 1 FROM og_bot.user_roles WHERE user_id = target_user_id AND role = 'vip'
  ) INTO exists_already;

  IF make_vip THEN
    IF exists_already THEN RETURN true; END IF;
    INSERT INTO og_bot.user_roles(user_id, role) VALUES (target_user_id, 'vip')
      ON CONFLICT (user_id, role) DO NOTHING;
    INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
      VALUES (target_user_id, 0, 'vip_grant',
              'admin_grant_vip' || COALESCE(' | ' || NULLIF(btrim(admin_notes), ''), ''));
    RETURN true;
  ELSE
    IF NOT exists_already THEN RETURN false; END IF;
    DELETE FROM og_bot.user_roles WHERE user_id = target_user_id AND role = 'vip';
    INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
      VALUES (target_user_id, 0, 'vip_revoke',
              'admin_revoke_vip' || COALESCE(' | ' || NULLIF(btrim(admin_notes), ''), ''));
    RETURN false;
  END IF;
END;
$$;

CREATE FUNCTION og_bot.set_vip_expiry_admin(target_user_id uuid, new_expires_at timestamp with time zone, admin_notes text DEFAULT NULL::text) RETURNS timestamp with time zone
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE had boolean;
BEGIN
  IF NOT (og_bot.has_role(auth.uid(), 'admin') OR og_bot.has_role(auth.uid(), 'boss')) THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM og_bot.profiles WHERE id = target_user_id) THEN
    RAISE EXCEPTION 'target_not_found';
  END IF;
  IF new_expires_at IS NOT NULL AND new_expires_at <= now() THEN
    RAISE EXCEPTION 'expiry_in_past';
  END IF;
  SELECT EXISTS (SELECT 1 FROM og_bot.user_roles WHERE user_id = target_user_id AND role = 'vip') INTO had;
  INSERT INTO og_bot.user_roles(user_id, role, expires_at) VALUES (target_user_id, 'vip', new_expires_at)
    ON CONFLICT (user_id, role) DO UPDATE SET expires_at = EXCLUDED.expires_at;
  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (target_user_id, 0, CASE WHEN had THEN 'vip_expiry_set' ELSE 'vip_grant' END,
      'admin_vip_expiry ' || COALESCE(to_char(new_expires_at, 'YYYY-MM-DD'), 'lifetime')
      || COALESCE(' | ' || NULLIF(btrim(admin_notes), ''), ''));
  RETURN new_expires_at;
END;
$$;

CREATE FUNCTION og_bot.songs_lock_nasheed() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'og_bot'
    AS $_$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.is_nasheed := COALESCE(NEW.is_nasheed, false)
      OR COALESCE(NEW.style, '') ~* '(^|,)\s*nasheed\s*(,|$)';
  ELSE
    NEW.is_nasheed := OLD.is_nasheed;
  END IF;
  RETURN NEW;
END $_$;

CREATE FUNCTION og_bot.songs_stamp_unlocked_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  IF NEW.unlocked IS TRUE AND (TG_OP = 'INSERT' OR OLD.unlocked IS DISTINCT FROM TRUE) THEN
    NEW.unlocked_at := COALESCE(NEW.unlocked_at, now());
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION og_bot.start_generation_charge(p_user uuid, p_song uuid, p_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE bal integer; prior integer; new_balance integer;
BEGIN
  IF p_user IS NULL OR p_song IS NULL OR p_reference IS NULL THEN RAISE EXCEPTION 'user_song_reference_required'; END IF;
  SELECT coin_balance INTO bal FROM og_bot.profiles WHERE id = p_user FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'profile_not_found'; END IF;
  -- Paid upfront: no minimum and no sample charge.
  IF EXISTS (SELECT 1 FROM og_bot.unlocked_songs WHERE user_id=p_user AND song_id=p_song) THEN
    RETURN jsonb_build_object('ok', true, 'charged', 0, 'balance', COALESCE(bal,0), 'unpaid_count', 0, 'warning', false);
  END IF;
  IF COALESCE(bal, 0) < 5 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'min_balance', 'balance', COALESCE(bal, 0), 'min_balance', 5);
  END IF;
  prior := og_bot.unpaid_track_count(p_user, p_song);
  IF prior >= 3 THEN
    new_balance := og_bot.deduct_coins(p_user, 2, p_reference);
    RETURN jsonb_build_object('ok', true, 'charged', 2, 'balance', new_balance, 'unpaid_count', prior + 1, 'warning', false);
  END IF;
  RETURN jsonb_build_object('ok', true, 'charged', 0, 'balance', bal, 'unpaid_count', prior + 1, 'warning', prior + 1 >= 3);
END; $$;

CREATE FUNCTION og_bot.start_vip_trial_once() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE uid uuid := auth.uid(); p record;
BEGIN
  IF uid IS NULL THEN RETURN jsonb_build_object('started', false); END IF;
  SELECT vip_trial_started_at, vip_trial_ends_at INTO p FROM og_bot.profiles WHERE id = uid;
  IF NOT FOUND OR p.vip_trial_started_at IS NOT NULL OR og_bot.has_role(uid, 'vip') THEN
    RETURN jsonb_build_object('started', false, 'ends_at', p.vip_trial_ends_at);
  END IF;
  PERFORM set_config('app.vip_trial_bypass', 'on', true);
  UPDATE og_bot.profiles SET vip_trial_started_at = now(), vip_trial_ends_at = now() + interval '15 days'
   WHERE id = uid AND vip_trial_started_at IS NULL;
  PERFORM set_config('app.vip_trial_bypass', 'off', true);
  RETURN jsonb_build_object('started', true, 'ends_at', now() + interval '15 days');
END $$;

CREATE FUNCTION og_bot.sync_owner_track_bonus(p_song uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE s og_bot.songs%ROWTYPE;
BEGIN
 SELECT * INTO s FROM og_bot.songs WHERE id=p_song;
 IF NOT FOUND OR s.suno_task_id IS NULL THEN RETURN; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(s.user_id::text || ':' || s.suno_task_id, 0));
 IF NOT EXISTS(SELECT 1 FROM og_bot.unlocked_songs WHERE song_id=s.id AND user_id=s.user_id AND source <> 'bundle_bonus') THEN RETURN; END IF;
 UPDATE og_bot.songs SET unlocked=true, revealed=true WHERE user_id=s.user_id AND suno_task_id=s.suno_task_id;
 INSERT INTO og_bot.unlocked_songs(user_id,song_id,source,cost_coins,reference)
 SELECT s.user_id,t.id,'bundle_bonus',0,'bonus:' || s.id::text FROM og_bot.songs t
 WHERE t.user_id=s.user_id AND t.suno_task_id=s.suno_task_id AND t.id<>s.id
 ON CONFLICT(user_id,song_id) DO NOTHING;
END $$;

CREATE FUNCTION og_bot.sync_referral_code_to_vip_id() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  IF NEW.og_vip_id IS NOT NULL AND NEW.referral_code IS DISTINCT FROM NEW.og_vip_id
     AND NOT EXISTS (SELECT 1 FROM og_bot.profiles WHERE referral_code = NEW.og_vip_id AND id <> NEW.id) THEN
    NEW.referral_code := NEW.og_vip_id;
  END IF;
  RETURN NEW;
END $$;

CREATE FUNCTION og_bot.tg_store_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'og_bot'
    AS $$
BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;

CREATE FUNCTION og_bot.unlock_community_track(_buyer uuid, _song_id uuid, _cost integer, _royalty integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  s record;
  claim_id uuid;
  new_balance integer;
  ref text := 'community_unlock:' || _song_id::text;
BEGIN
  IF _buyer IS NULL OR _song_id IS NULL THEN
    RAISE EXCEPTION 'buyer_and_song_required';
  END IF;
  IF _cost IS NULL OR _cost <= 0 THEN
    RAISE EXCEPTION 'amount_must_be_positive';
  END IF;
  IF COALESCE(_royalty, 0) < 0 OR COALESCE(_royalty, 0) > _cost THEN
    RAISE EXCEPTION 'invalid_royalty';
  END IF;

  SELECT id, user_id, status, revealed INTO s FROM og_bot.songs WHERE id = _song_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'song_not_found';
  END IF;
  IF s.user_id = _buyer THEN
    RAISE EXCEPTION 'owner_must_use_owner_purchase';
  END IF;
  IF s.status <> 'completed' THEN
    RAISE EXCEPTION 'song_not_ready';
  END IF;
  IF s.revealed IS FALSE THEN
    RAISE EXCEPTION 'not_revealed';
  END IF;

  PERFORM set_config('request.jwt.claim.role', 'service_role', true);

  INSERT INTO og_bot.unlocked_songs(user_id, song_id, source, cost_coins, reference)
  VALUES (_buyer, _song_id, 'community_purchase', _cost, ref)
  ON CONFLICT (user_id, song_id) DO NOTHING
  RETURNING id INTO claim_id;

  IF claim_id IS NULL THEN
    SELECT coin_balance INTO new_balance FROM og_bot.profiles WHERE id = _buyer;
    RETURN jsonb_build_object('ok', true, 'already', true, 'coin_balance', new_balance);
  END IF;

  -- Raises insufficient_coins, which also rolls back the claim above.
  new_balance := og_bot.deduct_coins(_buyer, _cost, ref);

  IF COALESCE(_royalty, 0) > 0 THEN
    UPDATE og_bot.profiles SET coin_balance = coin_balance + _royalty WHERE id = s.user_id;
    INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (s.user_id, _royalty, 'royalty', ref || ':from:' || _buyer::text);
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'already', false,
    'coin_balance', new_balance,
    'owner_id', s.user_id
  );
END;
$$;

CREATE FUNCTION og_bot.unpaid_track_count(p_user uuid, p_exclude uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
  SELECT COUNT(*)::integer
    FROM og_bot.songs s
   WHERE s.user_id = p_user
     AND s.is_variation IS NOT TRUE
     AND s.unlocked IS NOT TRUE
     AND s.status IN ('pending', 'processing', 'completed')
     AND (p_exclude IS NULL OR s.id <> p_exclude)
     AND s.created_at > COALESCE(
       (SELECT MAX(u.unlocked_at) FROM og_bot.songs u WHERE u.user_id = p_user AND u.unlocked IS TRUE),
       '-infinity'::timestamptz
     )
$$;

CREATE FUNCTION og_bot.unrevoke_og_bot_token(target_user_id uuid, admin_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
BEGIN
  IF NOT og_bot.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM og_bot.og_bot_tokens WHERE user_id = target_user_id) THEN
    RAISE EXCEPTION 'token_not_found';
  END IF;

  UPDATE og_bot.og_bot_tokens
    SET revoked_at = NULL, updated_at = now()
    WHERE user_id = target_user_id;

  INSERT INTO og_bot.coin_transactions(user_id, amount, type, reference)
    VALUES (target_user_id, 0, 'og_bot_token_unrevoke',
            'admin_unrevoke_og_bot_token' || COALESCE(' | ' || NULLIF(btrim(admin_notes), ''), ''));

  RETURN true;
END;
$$;

CREATE FUNCTION og_bot.validate_bot_token(p_token text, p_origin text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
DECLARE
  row_status text;
  row_domain text;
  origin_host text;
  allowed_host text;
BEGIN
  IF p_token IS NULL OR length(p_token) < 8 OR length(p_token) > 200 THEN
    RETURN false;
  END IF;
  IF p_origin IS NULL OR length(p_origin) > 500 THEN
    RETURN false;
  END IF;

  SELECT status, allowed_domain INTO row_status, row_domain
    FROM og_bot.bot_tokens WHERE token_string = p_token;

  IF NOT FOUND OR row_status <> 'active' THEN
    RETURN false;
  END IF;

  -- If no domain hardwired yet, treat as not-yet-bound (reject)
  IF row_domain IS NULL OR length(btrim(row_domain)) = 0 THEN
    RETURN false;
  END IF;

  -- Normalize: strip scheme + trailing slash + path
  origin_host  := lower(regexp_replace(p_origin,  '^https?://', ''));
  origin_host  := split_part(split_part(origin_host, '/', 1), ':', 1);
  allowed_host := lower(regexp_replace(row_domain, '^https?://', ''));
  allowed_host := split_part(split_part(allowed_host, '/', 1), ':', 1);

  RETURN origin_host = allowed_host;
END;
$$;

CREATE FUNCTION og_bot.verify_song_retry_token(p_token text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'og_bot'
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM og_bot.song_retry_scheduler
    WHERE singleton = true
      AND encode(extensions.digest(token, 'sha256'), 'hex') = encode(extensions.digest(coalesce(p_token, ''), 'sha256'), 'hex')
  );
$$;

