    timeframe text NOT NULL,
    direction text NOT NULL,
    entry numeric NOT NULL,
    entry_type text NOT NULL,
    stop numeric NOT NULL,
    tp1 numeric NOT NULL,
    tp2 numeric NOT NULL,
    tp3 numeric NOT NULL,
    confidence_pct integer NOT NULL,
    quality text NOT NULL,
    decimals integer DEFAULT 2 NOT NULL,
    pip numeric,
    card text,
    status text DEFAULT 'open'::text NOT NULL,
    best_target integer DEFAULT 0 NOT NULL,
    entered_at timestamp with time zone,
    closed_at timestamp with time zone,
    last_price numeric,
    last_candle_at timestamp with time zone,
    last_checked_at timestamp with time zone,
    last_edit_at timestamp with time zone,
    last_trend_check_at timestamp with time zone,
    expires_at timestamp with time zone NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    sender_worker text,
    CONSTRAINT trade_signals_direction_check CHECK ((direction = ANY (ARRAY['BUY'::text, 'SELL'::text]))),
    CONSTRAINT trade_signals_entry_type_check CHECK ((entry_type = ANY (ARRAY['market'::text, 'limit'::text]))),
    CONSTRAINT trade_signals_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'open'::text, 'tp1'::text, 'tp2'::text, 'tp3'::text, 'stopped'::text, 'breakeven'::text, 'expired'::text, 'unfilled'::text, 'cancelled'::text])))
);

CREATE TABLE og_bot.unlocked_songs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    song_id uuid NOT NULL,
    source text DEFAULT 'coins'::text NOT NULL,
    cost_coins integer,
    reference text,
    unlocked_at timestamp with time zone DEFAULT now() NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE og_bot.user_activity_log (
