    os text,
    device_type text,
    first_country text,
    last_country text,
    sign_in_count integer DEFAULT 1 NOT NULL,
    first_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE og_bot.user_notifications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    kind text NOT NULL,
    title text NOT NULL,
    body text,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    read boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE og_bot.user_onboarding_checks (
    user_id uuid NOT NULL,
    key text NOT NULL,
    ok boolean NOT NULL,
    detail text,
    latency_ms integer,
    checked_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE og_bot.user_preferences (
    user_id uuid NOT NULL,
    foul_mouth boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    text_scale numeric(3,2) DEFAULT 1.00 NOT NULL,
    density text DEFAULT 'comfortable'::text NOT NULL,
    messenger_mode text DEFAULT 'loner'::text NOT NULL,
    foul_intensity smallint DEFAULT 3 NOT NULL,
    og_memory boolean DEFAULT true NOT NULL,
    CONSTRAINT user_preferences_density_check CHECK ((density = ANY (ARRAY['comfortable'::text, 'compact'::text, 'spacious'::text]))),
    CONSTRAINT user_preferences_foul_intensity_range CHECK (((foul_intensity >= 0) AND (foul_intensity <= 3))),
    CONSTRAINT user_preferences_messenger_mode_check CHECK ((messenger_mode = ANY (ARRAY['loner'::text, 'community'::text]))),
    CONSTRAINT user_preferences_text_scale_check CHECK (((text_scale >= 0.85) AND (text_scale <= 1.50)))
);

