CREATE UNIQUE INDEX uniq_generation_charge_per_song ON og_bot.coin_transactions USING btree (user_id, reference) WHERE ((type = 'generation'::text) AND (reference IS NOT NULL) AND (created_at >= '2026-06-25 17:25:00+00'::timestamp with time zone) AND (reference ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'::text));

