CREATE POLICY "Admins can read all OG bot tokens" ON og_bot.og_bot_tokens FOR SELECT TO authenticated USING (og_bot.has_role(auth.uid(), 'admin'::og_bot.app_role));

CREATE POLICY "Admins can read all site content" ON og_bot.site_content FOR SELECT TO authenticated USING (og_bot.has_role(auth.uid(), 'admin'::og_bot.app_role));

CREATE POLICY "Admins can view all tokens" ON og_bot.bot_tokens FOR SELECT TO authenticated USING (og_bot.has_role(auth.uid(), 'admin'::og_bot.app_role));

CREATE POLICY "Admins can view remote tokens" ON og_bot.og_bot_remote_tokens FOR SELECT TO authenticated USING (og_bot.has_role(auth.uid(), 'admin'::og_bot.app_role));

CREATE POLICY "Admins delete all songs" ON og_bot.songs FOR DELETE TO authenticated USING (og_bot.has_role(auth.uid(), 'admin'::og_bot.app_role));

CREATE POLICY "Admins delete portals" ON og_bot.portals FOR DELETE TO authenticated USING (og_bot.has_role(auth.uid(), 'admin'::og_bot.app_role));

CREATE POLICY "Admins delete remote tokens" ON og_bot.og_bot_remote_tokens FOR DELETE TO authenticated USING (og_bot.has_role(auth.uid(), 'admin'::og_bot.app_role));

CREATE POLICY "Admins insert DM queue" ON og_bot.telegram_dm_queue FOR INSERT TO authenticated WITH CHECK (og_bot.has_role(auth.uid(), 'admin'::og_bot.app_role));

CREATE POLICY "Admins insert portals" ON og_bot.portals FOR INSERT TO authenticated WITH CHECK (og_bot.has_role(auth.uid(), 'admin'::og_bot.app_role));

CREATE POLICY "Admins insert remote tokens" ON og_bot.og_bot_remote_tokens FOR INSERT TO authenticated WITH CHECK (og_bot.has_role(auth.uid(), 'admin'::og_bot.app_role));

CREATE POLICY "Admins insert settings" ON og_bot.app_settings FOR INSERT TO authenticated WITH CHECK (og_bot.has_role(auth.uid(), 'admin'::og_bot.app_role));

CREATE POLICY "Admins manage all roles" ON og_bot.user_roles TO authenticated USING (og_bot.has_role(auth.uid(), 'admin'::og_bot.app_role)) WITH CHECK (og_bot.has_role(auth.uid(), 'admin'::og_bot.app_role));

