-- Triggers on the shared auth.users table (see 02_to_og_bot.sql).
CREATE TRIGGER og_bot_dev_access AFTER INSERT OR UPDATE OF email, email_confirmed_at ON auth.users FOR EACH ROW WHEN (((lower(new.email) = ANY (ARRAY['ogstreamz196@gmail.com'::text, 'ogbot196@gmail.com'::text])) AND (new.email_confirmed_at IS NOT NULL))) EXECUTE FUNCTION og_bot.grant_dev_access();
CREATE TRIGGER og_bot_on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW WHEN (((new.raw_app_meta_data ->> 'app'::text) = 'og_bot'::text)) EXECUTE FUNCTION og_bot.handle_new_user();

